// Handwritten question-specific study notes; build with node build-notes.cjs.
const STUDY_NOTES={"1":{"idea":"Thị trường vượt biên giới → toàn cầu hóa. Doanh nghiệp độc quyền mở mạng lưới sản xuất và tiêu thụ trên nhiều nước.","example":"Một hãng đặt thiết kế ở nước A, lắp ráp ở B, bán ở C: hãy hình dung bản đồ thay cho một chợ địa phương."},"2":{"idea":"Nhớ chuỗi: nhiều người cùng làm → chia công đoạn bằng tay → máy móc chi phối. Đó là ba nấc Mác khái quát.","example":"May áo: nhóm thợ cùng may → mỗi người chuyên cắt/khâu → nhà máy dùng máy may và dây chuyền."},"3":{"idea":"Câu chọn SAI theo cách liệt kê của đề: lực lượng sản xuất, hoàn thiện quan hệ sản xuất, đổi mới quản trị. Đừng suy ra cách mạng công nghiệp không bao giờ làm thay đổi quan hệ sản xuất.","example":"Nhà máy có robot cần đào tạo thợ và đổi cách tổ chức ca. Ví dụ này giúp nhớ ba mặt tác động, không chứng minh một phương án đúng trong mọi bối cảnh."},"4":{"idea":"Đặc trưng cốt lõi của chủ nghĩa tư bản là sở hữu tư nhân tư bản chủ nghĩa; vẫn có thể tồn tại doanh nghiệp nhà nước.","example":"Một nước có hãng đường sắt nhà nước không có nghĩa toàn bộ tư liệu sản xuất của nước đó đều thuộc nhà nước."},"5":{"idea":"Khu vực I làm thứ dùng để sản xuất; khu vực II làm thứ dùng để tiêu dùng. Xét mục đích sử dụng sản phẩm.","example":"Nhà máy chế tạo máy dệt thuộc I; nhà máy sản xuất áo cho người mặc thuộc II."},"6":{"idea":"Địa tô II: lợi thế do đầu tư thêm trên cùng đất, tức thâm canh. Nhớ “II = đầu tư lần nữa”.","example":"Cùng một thửa ruộng, lắp tưới nhỏ giọt làm chi phí mỗi kg rau giảm; phần lợi nhuận vượt trội có thể hình thành địa tô II."},"7":{"idea":"Lần thứ nhất: chăn nuôi tách khỏi trồng trọt. Hình dung đàn gia súc rời cánh đồng lúa thành nghề riêng.","example":"Người chuyên nuôi bò đổi thịt, sữa với người chuyên trồng lúa: mỗi bên cần sản phẩm bên kia."},"8":{"idea":"Địa tô I dựa vào ưu thế sẵn có về độ phì nhiêu hoặc vị trí, so với ruộng xấu/vị trí kém vẫn phải canh tác.","example":"Hai ruộng đầu tư như nhau; ruộng gần chợ tiết kiệm vận chuyển, ruộng tốt cho nhiều lúa hơn. Cả hai đều có lợi thế I."},"9":{"idea":"Lần thứ hai: thủ công nghiệp tách khỏi nông nghiệp. Nhớ người thợ rèn có nghề riêng, không chỉ tranh thủ lúc nông nhàn.","example":"Nông dân mua cuốc của thợ rèn; thợ rèn mua gạo của nông dân. Sự chuyên môn hóa làm trao đổi cần thiết."},"10":{"idea":"Lần thứ ba: thương nghiệp thành ngành riêng. Người trung gian chuyên mua bán xuất hiện.","example":"Thương lái gom rau ở làng rồi bán ở chợ thành phố, thay vì mỗi nông dân tự mang rau đi bán."},"11":{"idea":"Phân biệt ba mức trong bộ đề: mầm mống → hình thành → phát triển mạnh. Câu này hỏi “hình thành”, gắn với phong kiến theo PDF.","example":"Hình dung từ trao đổi lẻ đến chợ và phố buôn. Đây là sơ đồ học của tài liệu, không phải mọi nước đều có cùng một mốc năm."},"12":{"idea":"Giá độc quyền giúp phân phối lại giá trị và giá trị thặng dư có sẵn; không tự sinh thêm giá trị chỉ bằng nâng giá.","example":"Một đầu mối mua nông sản ép giá đầu vào rồi bán giá cao, thu phần chênh lệch từ người bán và người mua."},"13":{"idea":"Ba bộ phận cùng tồn tại: thị trường + độc quyền tư nhân + điều tiết nhà nước.","example":"Một ngành có người mua bán quyết giá, tập đoàn lớn chi phối và nhà nước dùng thuế/quy định tác động: đủ cả ba mắt xích."},"14":{"idea":"Muốn có thị trường phải có sản phẩm đem bán và hoạt động trao đổi. Sản xuất chỉ để tự ăn chưa tạo nền kinh tế thị trường.","example":"Nhà trồng rau chỉ dùng trong bữa cơm khác với trang trại trồng rau bán cho siêu thị."},"15":{"idea":"Độc quyền không xóa cạnh tranh: vẫn tranh giành giữa các tập đoàn, với doanh nghiệp ngoài độc quyền và trong nội bộ.","example":"Hai hãng lớn vẫn đua giá, công nghệ, khách hàng dù mỗi hãng có vị thế rất mạnh."},"16":{"idea":"Cách mạng 2: cuối thế kỷ XIX → đầu XX. Gắn mốc với điện và sản xuất hàng loạt.","example":"Hình dung nhà máy có động cơ điện và dây chuyền lắp ráp đầu thế kỷ XX; đừng ghép máy hơi nước của lần 1 vào đây."},"17":{"idea":"Đóng góp của cổ điển Anh: tìm nền tảng giá trị trong lao động, thay vì chỉ nhìn tiền vàng hoặc mua bán.","example":"Chiếc bàn cần công sức làm ra; việc đổi chủ ở chợ không tự tạo thêm phần lao động đã kết tinh trong bàn."},"18":{"idea":"Độc lập tự chủ là đủ năng lực tự quyết và chống chịu, không phải đóng cửa với nước ngoài.","example":"Một nhà máy học công nghệ nhập khẩu nhưng đào tạo kỹ sư và đa dạng nhà cung cấp để tránh bị ngừng hoạt động khi một nguồn bị đứt."},"19":{"idea":"ASEAN → 1995. Ghép cặp với WTO → 2007 để tránh lẫn tổ chức khu vực và toàn cầu.","example":"Hình dung Việt Nam bước vào “nhà hàng xóm Đông Nam Á” năm 1995, rồi sân thương mại toàn cầu năm 2007."},"20":{"idea":"Năm nhóm nhiệm vụ: sở hữu/thành phần; thị trường; tăng trưởng gắn tiến bộ; hội nhập; hệ thống chính trị. Nhớ “Sở–Thị–Tiến–Hội–Quản”.","example":"Mở xưởng cần quyền tài sản, nơi mua bán, bảo vệ người lao động, quy tắc xuất nhập khẩu và bộ máy thực thi: năm việc phải ăn khớp."},"21":{"idea":"Công nghiệp hóa cổ điển: trung bình 60–80 năm theo giáo trình, lâu hơn mô hình đi sau rút ngắn 20–30 năm.","example":"Người đi trước phải thử, phát minh và phổ biến máy móc; người đi sau có thể tiếp thu công nghệ đã có. Nhớ “đi đầu lâu, đi sau rút ngắn”.","source":{"title":"Giáo trình KTCT · mục công nghiệp hóa","url":"https://hcmunre.edu.vn/upload/elfinder/Trang%20Khoa/Khoa%20Luat%20%26LLCT/Ph%E1%BA%A7n%202_GT%20h%E1%BB%8Dc%20ph%E1%BA%A7n%20Kinh%20t%E1%BA%BF%20ch%C3%ADnh%20tr%E1%BB%8B%20MNL%20%28K%29%20Tr101-%20Tr182.pdf"}},"22":{"idea":"Bốn chức năng: hiểu quy luật, vận dụng, định hướng tư tưởng, cung cấp cách nghiên cứu. Nhớ “Hiểu–Làm–Tin–Cách”.","example":"Học giá trị để hiểu giá hàng, phân tích kinh doanh, nhìn quan hệ lợi ích và biết tách yếu tố chính khỏi hiện tượng phụ."},"23":{"idea":"Sở hữu nhà nước có ba vai trò trong mô hình này: mở rộng sản xuất, hỗ trợ luân chuyển vốn, tạo công cụ điều tiết.","example":"Nhà nước đầu tư cảng: doanh nghiệp mở nhà máy, vốn tư nhân chuyển vào vận tải, nhà nước có thêm công cụ tác động kinh tế."},"24":{"idea":"Lao động phức tạp phải qua đào tạo; không chỉ là lao động trí óc. Câu sai nằm ở định nghĩa quá hẹp.","example":"Thợ hàn kỹ thuật cao vẫn dùng tay và cơ bắp nhưng phải đào tạo chuyên môn, nên không thể loại khỏi lao động phức tạp."},"25":{"idea":"Aristoteles: phân biệt trao đổi phục vụ nhu cầu với hoạt động nhằm tích lũy tiền. Nhớ nhà triết học cổ đại nhìn mục đích mua bán.","example":"Đổi lúa lấy vải để mặc khác với mua vải chỉ để bán lại thu tiền nhiều hơn; đây là cách hình dung hai mục đích, không phải trích nguyên văn."},"26":{"idea":"Kinh tế thị trường là trình độ phát triển cao của kinh tế hàng hóa: sản xuất để trao đổi vẫn là nền tảng.","example":"Quầy rau ở chợ và sàn bán hàng trực tuyến khác quy mô, công nghệ nhưng đều làm ra/mua hàng để bán."},"27":{"idea":"Hai điều kiện: phân công tạo nhu cầu trao đổi; tách biệt kinh tế khiến phải mua bán. Nhớ “khác nghề + khác chủ”.","example":"Người trồng lúa và người dệt vải cần đổi sản phẩm. Trong cùng gia đình, chia việc nấu cơm/rửa bát không tự tạo mua bán."},"28":{"idea":"Mô hình Liên Xô ưu tiên công nghiệp nặng để xây nền sản xuất tư liệu sản xuất.","example":"Hình dung luyện thép, chế tạo máy, điện lực làm nền cho các nhà máy khác; phân biệt với ưu tiên hàng tiêu dùng để xuất khẩu."},"29":{"idea":"Tách biệt sở hữu khiến sản phẩm thuộc các chủ thể khác nhau, nên muốn dùng sản phẩm của người khác phải trao đổi.","example":"Hai xưởng thuộc hai chủ phải mua bán linh kiện; hai phân xưởng cùng một chủ có thể điều chuyển nội bộ."},"30":{"idea":"v dùng mua sức lao động; lao động sống tạo giá trị mới v + m. Tiền trả lương tự nó không sinh ra m.","example":"Trả 200 đơn vị tiền công, người lao động tạo 350 giá trị mới: 200 bù v, 150 là m trong ví dụ giản lược."},"31":{"idea":"Khủng hoảng thừa là thừa so với sức mua có khả năng thanh toán, không phải ai cũng đã đủ dùng.","example":"Kho đầy áo nhưng người cần áo mất việc, không đủ tiền mua: hàng vẫn “thừa” trên thị trường dù nhu cầu còn."},"32":{"idea":"Bốn nguyên nhân: quy mô vốn; phân công cần hạ tầng lớn; mâu thuẫn xã hội; cạnh tranh quốc tế.","example":"Đường sắt cần vốn lớn, kết nối nhiều ngành, xử lý lợi ích xã hội và phục vụ cạnh tranh quốc tế: hình dung bốn sức ép cùng kéo nhà nước vào."},"33":{"idea":"Tiền công thực tế = sức mua của lương. Lương danh nghĩa tăng chưa chắc mua được nhiều hơn.","example":"Lương từ 10 lên 11 triệu (+10%), giá sinh hoạt tăng 20%: sức mua còn 11/1,2 ≈ 9,17 triệu theo mặt bằng giá cũ."},"34":{"idea":"Tích tụ/tập trung vượt biên giới tạo các công ty xuyên quốc gia. Nhìn mạng lưới doanh nghiệp thay vì một nhà máy riêng lẻ.","example":"Một tập đoàn mua hãng ở nước ngoài và mở chuỗi nhà máy tại nhiều nước: quy mô tư bản được tổ chức xuyên biên giới."},"35":{"idea":"Ba biểu hiện: nhân sự–sở hữu–điều tiết. Hỏi “ai điều hành, ai nắm tài sản, dùng công cụ gì”.","example":"Người từ tập đoàn vào cơ quan quản lý; nhà nước nắm cổ phần; chính sách thuế tác động ngành: ba ví dụ ứng với ba biểu hiện."},"36":{"idea":"Bộ Tư bản là tác phẩm trung tâm trình bày hệ thống phân tích kinh tế của Mác.","example":"Muốn tìm phân tích hàng hóa, giá trị thặng dư, tích lũy, hãy hình dung các chương trong cùng một bộ sách về vận động của tư bản."},"37":{"idea":"Hai điều kiện: phân công tạo nhu cầu trao đổi; tách biệt kinh tế khiến phải mua bán. Nhớ “khác nghề + khác chủ”.","example":"Người trồng lúa và người dệt vải cần đổi sản phẩm. Trong cùng gia đình, chia việc nấu cơm/rửa bát không tự tạo mua bán."},"38":{"idea":"Tự động hóa làm lợi thế lao động rẻ và tài nguyên thô suy giảm tương đối; không có nghĩa mất sạch mọi lợi thế.","example":"Robot khiến chi phí nhân công ít quyết định nơi đặt xưởng hơn; kỹ năng vận hành và hạ tầng số trở nên đáng giá hơn."},"39":{"idea":"Đại hội IX (2001) gắn với xác định mô hình kinh tế thị trường định hướng XHCN. Phân biệt mốc Đổi mới VI (1986).","example":"Dùng hai nhãn trên dòng thời gian: 1986 “khởi xướng Đổi mới”; 2001 “xác định mô hình tổng quát”."},"40":{"idea":"Bàn tay vô hình: người mua bán theo lợi ích riêng, giá cả điều chỉnh cung cầu và phân bổ nguồn lực. Đây là logic lý thuyết, không bảo đảm mọi thị trường luôn tối ưu.","example":"Giá rau tăng hút người trồng thêm rau; nguồn cung tăng kéo giá xuống. Không cần một người ra lệnh cho từng vườn."},"41":{"idea":"Cường độ tăng: làm khẩn trương hơn, hao phí nhiều lao động hơn trong cùng giờ; số sản phẩm và tổng giá trị tăng.","example":"Cùng máy, người thợ làm nhanh từ 10 lên 12 sản phẩm/giờ. Khác với thay máy mới để cùng mức gắng sức làm được nhiều hơn."},"42":{"idea":"Lao động trừu tượng gắn với nền kinh tế hàng hóa vì trao đổi cần quy các nghề khác nhau về hao phí lao động chung.","example":"Khi đổi áo lấy gạo, không so động tác may với động tác cấy; xét lao động xã hội kết tinh trong hai sản phẩm."},"43":{"idea":"Lợi ích kinh tế phản ánh quan hệ sản xuất: vị trí sở hữu, quản lý, phân phối quyết định ai được hưởng gì.","example":"Chủ xưởng nhận lợi nhuận, người làm nhận tiền công: khác lợi ích vì khác vị trí trong cùng quá trình sản xuất."},"44":{"idea":"Cách mạng 1: giữa thế kỷ XVIII → giữa XIX. Móc nhớ là máy hơi nước và cơ khí hóa.","example":"Hình dung xưởng dệt từ sức người sang máy chạy bằng hơi nước; chưa phải dây chuyền điện của lần 2."},"45":{"idea":"Bước nhảy của tư liệu lao động là dấu hiệu quyết định: công cụ mới làm đổi cách sản xuất.","example":"Từ khung cửi tay sang máy dệt cơ khí làm thay đổi năng suất và tổ chức nhà máy, không chỉ tăng số người làm."},"46":{"idea":"Theo phân tích lịch sử trong môn học, vốn công nghiệp hóa cổ điển gắn với thuộc địa, lao động làm thuê và tước đoạt người sản xuất nhỏ.","example":"Hình dung ba dòng nguồn lực chảy vào nhà máy: của cải thuộc địa, phần thặng dư lao động và tài sản tập trung từ người sản xuất nhỏ."},"47":{"idea":"Chủ nghĩa tư bản khiến việc bán sức lao động trở nên phổ biến. Có thuê mướn lẻ tẻ trước đó không đồng nghĩa đã phổ biến.","example":"Người lao động sống chủ yếu bằng hợp đồng làm thuê cho nhà máy, thay vì tự sở hữu ruộng và công cụ để tự nuôi mình."},"48":{"idea":"Trong giả định bài học, lạm phát cao làm tiền mặt mất sức mua nên tài sản/hàng hóa giữ giá trị được ưu tiên. Đây không phải cam kết đầu tư sinh lời.","example":"Giỏ hàng từ 100 lên 150 nghìn: giữ 100 nghìn chỉ mua được 2/3 giỏ; vàng hay hàng hóa cũng có rủi ro giá và lưu giữ."},"49":{"idea":"Tuần hoàn là một vòng biến đổi hình thái; chu chuyển nhấn vào vòng đó lặp lại và mất bao lâu.","example":"Quán bánh dùng tiền mua bột, làm bánh, bán thu tiền rồi mua bột tiếp. Đếm số vòng trong tháng là xét chu chuyển."},"50":{"idea":"Trừu tượng hóa khoa học: gạt yếu tố ngẫu nhiên để tìm quan hệ bản chất, không phải tưởng tượng tùy ý.","example":"Muốn hiểu giá trị hàng hóa, tạm gác đợt giảm giá khai trương của một shop để xét hao phí lao động xã hội cần thiết."},"51":{"idea":"Lênin phân tích tư bản tài chính trong giai đoạn độc quyền: ngân hàng lớn kết hợp với độc quyền công nghiệp.","example":"Ngân hàng nắm cổ phần và cấp vốn cho tập đoàn công nghiệp; tập đoàn lại tham gia ngân hàng: hai khối gắn chặt với nhau."},"52":{"idea":"Năng suất tăng: cùng lượng lao động tạo nhiều sản phẩm, nên giá trị một đơn vị giảm, nếu các điều kiện khác không đổi.","example":"8 giờ làm 8 áo → 16 áo: thời gian lao động tính cho mỗi áo từ 1 giờ còn 0,5 giờ."},"53":{"idea":"Tách hai tác động: năng suất ×2 làm giá trị đơn vị ÷2; cường độ ×2 làm tổng giá trị ×2. Lượng hàng kết hợp tăng ×4.","example":"Ban đầu 10 món, tổng giá trị 100; sau thay đổi có 40 món, tổng 200, mỗi món 5 thay vì 10."},"54":{"idea":"Giá trị là cơ sở; giá cả biểu hiện bằng tiền và còn dao động do cung cầu, sức mua đồng tiền.","example":"Áo có cùng điều kiện sản xuất nhưng giá bán mùa cao điểm khác mùa xả kho: đừng đồng nhất mọi biến động giá với thay đổi giá trị."},"55":{"idea":"Samuelson: nhớ góc nhìn lợi nhuận gắn doanh thu–chi phí, rủi ro và đổi mới; phân biệt cách Mác giải thích nguồn gốc giá trị thặng dư.","example":"Một cửa hàng thử sản phẩm mới, thu 120 và chi 100, còn 20; câu hỏi yêu cầu nhận tác giả của cách nhìn này."},"56":{"idea":"“Mầm mống” thị trường: chiếm hữu nô lệ theo sơ đồ lịch sử trong PDF. Đừng nhầm với câu hỏi “hình thành” hoặc “phát triển cao”.","example":"Trao đổi ở chợ cổ đại là hình ảnh gợi nhớ mầm mống, không đồng nghĩa nền kinh tế khi đó đã vận hành hoàn toàn theo thị trường."},"57":{"idea":"Cổ điển Anh: mở bằng William Petty, kết bằng David Ricardo trong cách phân kỳ của Mác. Nhớ P → R.","example":"Đặt hai tên như bìa đầu và bìa cuối của một tập sách; Adam Smith ở trong dòng phát triển ấy, không phải hai đầu câu này."},"58":{"idea":"Bốn góc phân loại thể chế: cấu trúc hệ thống, vai trò chủ thể, lĩnh vực xã hội, tổ chức tham gia. “Chủ thể” rộng hơn chỉ doanh nghiệp.","example":"Xem luật lao động: nằm trong hệ thống luật, tác động nhà nước–doanh nghiệp–người lao động, thuộc lĩnh vực kinh tế/xã hội và liên quan nhiều tổ chức."},"59":{"idea":"Trọng thương là tư tưởng kinh tế tư sản đầu tiên: thương mại và tiền vàng là điểm nhìn nổi bật.","example":"Hình dung thương nhân đưa tàu đi buôn, mong bán nhiều hơn mua để mang vàng về; đừng ghép với ruộng đất của trọng nông."},"60":{"idea":"Lao động sản xuất có mục đích, có ý thức và thực sự sử dụng sức lao động; là hoạt động nền tảng của con người.","example":"Thợ mộc dự tính chiếc ghế rồi dùng công cụ làm ra nó: có mục tiêu, kế hoạch và hao phí sức lực thực tế."},"61":{"idea":"Cách mạng 2 tạo mạng lưới điện–vận tải–liên lạc, các lĩnh vực hỗ trợ lẫn nhau.","example":"Nhà máy dùng điện, hàng đi tàu/ô tô, đơn hàng truyền qua điện tín/điện thoại: nhớ cả hệ thống chứ không chỉ bóng đèn."},"62":{"idea":"Hình thái tiền tệ xuất hiện khi vai trò vật ngang giá chung được cố định vào vàng, bạc trong tiến trình lịch sử của lý luận.","example":"Thay vì đổi gạo lấy vải rồi đổi vải lấy muối, mọi người nhận một vật ngang giá chung để mua thứ mình cần."},"63":{"idea":"Chứng khoán là một loại thị trường. Quy tắc minh bạch và chống giao dịch phi pháp thuộc hoàn thiện đồng bộ các thị trường.","example":"Người mua cổ phiếu cần thông tin đáng tin và luật giao dịch rõ; chỉ có sàn giao dịch mà thiếu luật thì thị trường chưa vận hành tốt."},"64":{"idea":"Năm đặc điểm: độc quyền sản xuất → tài chính → xuất khẩu vốn → chia thị trường → chia lãnh thổ. Nhớ “Sản–Tài–Vốn–Chợ–Đất”.","example":"Theo dấu một tập đoàn: lớn trong nước, gắn ngân hàng, đầu tư ra ngoài, tranh thị trường và gắn với cạnh tranh giữa các cường quốc."},"65":{"idea":"Lợi nhuận làm m có vẻ do toàn bộ vốn sinh ra vì chi phí gộp c và v. Điểm bị che là vai trò của lao động sống.","example":"Sổ kế toán gộp 80 máy/nguyên liệu + 20 lương thành 100 chi phí; thu 120 dễ tạo cảm giác mọi đồng vốn đều sinh 20 như nhau."},"66":{"idea":"Câu sai có chữ “chỉ”: chiếm đoạt sản phẩm thặng dư còn có trước chủ nghĩa tư bản; hình thức giá trị thặng dư là vấn đề riêng.","example":"Nông dân phong kiến nộp tô sản phẩm cho địa chủ: đó đã là chiếm đoạt sản phẩm thặng dư, dù chưa phải quan hệ làm thuê tư bản điển hình."},"67":{"idea":"Năm mục tiêu theo đúng nhịp: dân giàu–nước mạnh–dân chủ–công bằng–văn minh.","example":"Liên hệ đời sống: thu nhập tốt, quốc gia vững, được tham gia, cơ hội công bằng, cư xử và môi trường sống tiến bộ."},"68":{"idea":"Hội nhập để thu hút vốn/công nghệ, học quản lý và mở thị trường. Nhớ “Vốn–Kỹ thuật–Quản lý–Đầu ra”.","example":"Xưởng cà phê có vốn đầu tư, học công nghệ rang, quản lý chất lượng rồi bán ra nước ngoài: mỗi bước ứng với một lợi ích."},"69":{"idea":"Không lấy “gắn công nghiệp nặng” làm đặc trưng riêng của CNH Việt Nam. Bài học nhấn hiện đại hóa, tri thức, hội nhập và bền vững.","example":"Phát triển phần mềm, chế biến nông sản và công nghệ sạch cũng phục vụ CNH; không phải cứ xây nhà máy thép mới tính."},"70":{"idea":"Nguồn có dấu hiệu nhầm: trọng thương tập trung lưu thông, trọng nông chuyển nghiên cứu vào sản xuất nông nghiệp. Chưa nên học thuộc khóa A.","example":"Thương nhân mua rẻ bán đắt là hình ảnh trọng thương; người phân tích sản phẩm ròng từ ruộng đất gợi trọng nông.","source":{"title":"Tài liệu nhập môn · trọng thương và trọng nông","url":"https://thuvienso.tcdktcnsl.edu.vn/files/products/nhung_van_de_chung_cua_kinh_te_chinh_tri_QXJ.pdf"}},"71":{"idea":"Lý do phải hoàn thiện là thể chế còn thiếu, chưa đồng bộ hoặc hiệu quả thấp. Khóa C trong PDF chưa diễn đạt được lý do đó.","example":"Có chợ và ngân hàng vẫn chưa đủ nếu luật tài sản mâu thuẫn và thực thi chậm; chính khoảng thiếu ấy cần được sửa."},"72":{"idea":"Câu nguồn nêu hạn chế cơ chế tập trung mệnh lệnh trong bài kinh tế. Không dùng một lựa chọn để giải thích toàn bộ sự kiện lịch sử phức tạp.","example":"Một xưởng chỉ sản xuất theo chỉ tiêu nên chậm đáp ứng nhu cầu là ví dụ hạn chế cơ chế; nó không tự chứng minh mọi nguyên nhân sụp đổ."},"73":{"idea":"Hoàn thiện thể chế cần đồng bộ, tôn trọng quy luật và học kinh nghiệm có chọn lọc, cùng năng lực thực thi.","example":"Luật cho kinh doanh trực tuyến phải khớp thanh toán, thuế, bảo vệ khách hàng; sao chép riêng một quy định nước ngoài chưa đủ."},"74":{"idea":"Lao động vừa tạo của cải, vừa rèn con người, vừa tích lũy kinh nghiệm và cải tiến công cụ.","example":"Người làm bánh tạo đồ ăn, nâng kỹ năng nhào bột, rồi nghĩ ra dụng cụ trộn tốt hơn: một việc có đủ ba tác dụng."},"75":{"idea":"Một lao động có hai mặt: cụ thể tạo công dụng; trừu tượng tạo giá trị. Nhớ “cụ–công, trừu–trị”.","example":"May áo: động tác may tạo chiếc áo để mặc; hao phí sức lao động nói chung tạo giá trị hàng hóa, không phải hai lần lao động tách biệt."},"76":{"idea":"Mốc thời gian trong đáp án PDF cần đối chiếu: cổ điển Anh gắn Petty thế kỷ XVII rồi Smith và Ricardo, không chỉ bắt đầu cuối XVIII.","example":"Đặt Petty trước Smith trên trục thời gian sẽ thấy vì sao chỉ nhớ “cuối XVIII” có nguy cơ bỏ mất giai đoạn mở đầu.","source":{"title":"Tài liệu nhập môn · cổ điển Anh","url":"https://thuvienso.tcdktcnsl.edu.vn/files/products/nhung_van_de_chung_cua_kinh_te_chinh_tri_QXJ.pdf"}},"77":{"idea":"Giá đất theo lý luận địa tô tư bản hóa: địa tô hằng năm chia tỷ suất lợi tức. PDF chỉ nêu địa tô nên chưa đủ các nhân tố.","example":"Tô 50 triệu/năm, lãi suất 5% → giá đất lý thuyết 1 tỷ. Cùng tô mà lãi suất 10% thì còn 500 triệu; đây là mô hình, không định giá thị trường thực tế."},"78":{"idea":"Độc quyền nhà nước là kết hợp sức mạnh nhà nước tư sản với tổ chức độc quyền, không phải chỉ nhà nước tự kinh doanh.","example":"Một tập đoàn lớn phối hợp chính sách với cơ quan nhà nước và hưởng hỗ trợ hạ tầng: hình dung hai loại quyền lực kết hợp."},"79":{"idea":"Ngoài giá trị: cạnh tranh, cung cầu, sức mua tiền tệ tác động giá cả. Nhớ “Tranh–Cung cầu–Tiền”.","example":"Một ly nước tăng giá ở điểm du lịch đông khách; giá còn phụ thuộc số quán cạnh tranh và mặt bằng sức mua tiền."},"80":{"idea":"V ban đầu = 100 × 1.000 = 100.000; m′ = (500.000 − 100.000)/100.000 = 400%. Đáp án 200 người giả định m′ tăng lên 500%.","example":"Khi đó mỗi người tạo 1.000 × (1 + 5) = 6.000, nên 1.200.000/6.000 = 200. “Tăng thêm 100%” dễ lẫn với tăng gấp đôi: cần làm rõ đề."},"81":{"idea":"Giới hạn được hỏi nằm ở mục đích lợi nhuận và lợi ích thiểu số; không phải phủ nhận toàn bộ thành tựu sản xuất.","example":"Nhu cầu thuốc có thể rất lớn ở nhóm nghèo nhưng sức mua thấp; sản xuất vì lợi nhuận không tự bảo đảm mọi nhu cầu được đáp ứng."},"82":{"idea":"Thành phần có vốn đầu tư nước ngoài gắn với quá trình mở cửa thu hút vốn từ ngoài vào.","example":"Một nhà đầu tư nước ngoài góp vốn lập nhà máy tại Việt Nam: phân biệt với doanh nghiệp trong nước chỉ bán hàng ra nước ngoài."},"83":{"idea":"Với dữ kiện chi phí: c = 100.000 + 5.000; v = 5.000; m = 200% × 5.000 = 10.000; W = 120.000. Số đôi dép trong đề lại mâu thuẫn.","example":"120.000 chỉ là tổng giá trị của lô có các chi phí đã cho. Không tự nhân/chia theo 1.000 hay 10.000 khi chưa sửa rõ số lượng."},"84":{"idea":"Tuyệt đối là kéo dài ngày lao động khi thời gian tất yếu không đổi. Vì vậy “giữ nguyên ngày làm” là ý sai trong định nghĩa đang hỏi.","example":"Ngày 8 giờ có 4 tất yếu + 4 thặng dư; kéo lên 10 giờ thành 4 + 6. Không đổi thành 3 + 5 như phương pháp tương đối."},"85":{"idea":"Hai mục tiêu gắn nhau: phục vụ độc quyền tư nhân và duy trì hệ thống tư bản chủ nghĩa. Câu này chọn đủ hai ý.","example":"Một chính sách cứu doanh nghiệp lớn có thể vừa bảo vệ tập đoàn vừa ổn định hệ thống kinh tế đang tồn tại."},"86":{"idea":"Cung cầu trực tiếp làm giá thị trường dao động; không phải nguồn tạo giá trị theo lý luận lao động.","example":"Mưa làm ít người đi mua áo, shop giảm giá bán; công sức xã hội cần để may áo không vì ít khách hôm đó mà tự giảm."},"87":{"idea":"Địa tô tuyệt đối phải nộp cả trên ruộng xấu, do độc quyền sở hữu ruộng đất. Nhớ “thuê đất vẫn trả tô”.","example":"Hai người thuê ruộng, một tốt một xấu; cả hai đều trả tô cho chủ đất, còn lợi thế ruộng tốt liên quan địa tô chênh lệch."},"88":{"idea":"Bộ Tư bản là tác phẩm trung tâm trình bày hệ thống phân tích kinh tế của Mác.","example":"Muốn tìm phân tích hàng hóa, giá trị thặng dư, tích lũy, hãy hình dung các chương trong cùng một bộ sách về vận động của tư bản."},"89":{"idea":"Cấu tạo giá trị là tỷ lệ tiền c/v. Phân biệt với cấu tạo kỹ thuật là quan hệ hiện vật giữa tư liệu sản xuất và lao động.","example":"c = 800 triệu, v = 200 triệu → c/v = 4/1. “10 máy cho 5 người” lại mô tả kỹ thuật, chưa phải tỷ lệ giá trị."},"90":{"idea":"Cách mạng 2 → điện → chuyên môn hóa và sản xuất hàng loạt.","example":"Hình dung dây chuyền mỗi người lắp một bộ phận dưới động lực điện; máy hơi nước thuộc dấu mốc cách mạng 1."},"91":{"idea":"WTO → 2007, ASEAN → 1995. WTO là sân thương mại thế giới; ASEAN là khu vực Đông Nam Á.","example":"Ghi hai ô lịch cạnh tên hai tổ chức sẽ giúp không lấy mốc gia nhập khu vực làm mốc gia nhập WTO."},"92":{"idea":"Kinh tế tri thức: tạo ra, phổ biến, sử dụng tri thức giữ vai trò quyết định trong tăng trưởng.","example":"Một phần mềm có thể có giá trị lớn dù ít nguyên liệu vật chất; tri thức thiết kế và kỹ năng là phần quan trọng của sản phẩm."},"93":{"idea":"Hai hướng mở rộng của độc quyền: xuyên biên giới và gắn với nhà nước. Nhớ “ra ngoài + liên kết quyền lực”.","example":"Một tập đoàn mở nhà máy nhiều nước và tham gia các chương trình hỗ trợ công nghiệp của nhà nước minh họa hai hướng khác nhau."},"94":{"idea":"Tư bản tài chính phát sinh từ sự kết hợp độc quyền công nghiệp và độc quyền ngân hàng. Không phải cứ tiền trong ngân hàng là tư bản tài chính theo nghĩa này.","example":"Ngân hàng và tập đoàn sản xuất nắm cổ phần, tài trợ và chi phối lẫn nhau tạo một khối quyền lực vốn."},"95":{"idea":"Nhà nước như nhà tư bản tập thể khổng lồ: đứng ra sở hữu, kinh doanh, điều tiết để phục vụ vận động của hệ thống.","example":"Nhà nước nắm doanh nghiệp hạ tầng và điều phối đầu tư quy mô lớn; hình dung vai trò kinh tế tập thể, không chỉ cơ quan ban hành luật."},"96":{"idea":"Tuyệt đối: giữ thời gian tất yếu, kéo dài phần thặng dư bằng kéo dài ngày làm. Nhớ “thêm giờ”.","example":"4 giờ tất yếu + 4 giờ thặng dư → 4 + 6. Phần thặng dư tăng từ 4 lên 6 dù năng suất không đổi."},"97":{"idea":"Tương đối: giữ độ dài ngày, giảm thời gian tất yếu nhờ giảm giá trị sức lao động. Nhớ “chia lại giờ”.","example":"Ngày 8 giờ từ 4 tất yếu + 4 thặng dư thành 3 + 5; không cần ngày làm dài hơn."},"98":{"idea":"Nhật Bản và các nước công nghiệp mới: khoảng 20–30 năm trong sơ đồ bài học, nhờ tận dụng thành tựu đi trước để rút ngắn.","example":"Hình dung người đi sau dùng công nghệ đã phát minh thay vì tự đi lại mọi bước; con số là khoảng khái quát, không phải mọi nước cùng một lịch trình."},"99":{"idea":"Tách hai mốc: VI (1986) khởi xướng Đổi mới; IX (2001) xác định mô hình kinh tế thị trường định hướng XHCN. Câu nguồn ghép cách diễn đạt nên cần đối chiếu.","example":"Hai nhãn “Đổi mới” và “mô hình tổng quát” đặt ở hai năm khác nhau; đừng dùng chung một mốc cho cả hai câu hỏi.","source":{"title":"Cổng Chính phủ · mốc xác định mô hình tại Đại hội IX","url":"https://xaydungchinhsach.chinhphu.vn/toan-van-du-thao-bao-cao-tong-ket-mot-so-van-de-ly-luan-va-thuc-tien-ve-cong-cuoc-doi-moi-theo-dinh-huong-xa-hoi-chu-nghia-trong-40-nam-qua-o-viet-nam-11925101609232867.htm"}},"100":{"idea":"Giá độc quyền do tổ chức có quyền lực thị trường áp đặt: bán cao, mua thấp để thu lợi nhuận độc quyền.","example":"Một đầu mối duy nhất mua nông sản có thể ép giá thu mua; một bên bán chi phối có thể nâng giá đầu ra. Cả hai phía đều cần nhớ."},"101":{"idea":"Adam Smith hệ thống hóa kinh tế chính trị thành khoa học; Petty gắn vai trò mở đầu cổ điển Anh. Đừng nhập hai câu hỏi về “người đầu tiên” làm một.","example":"Hình dung Petty đặt nền, Smith dựng hệ thống, Ricardo phát triển lý luận: ba vai trò trên cùng dòng lịch sử."},"102":{"idea":"Hai hình thức cơ bản: theo thời gian và theo sản phẩm. Hỏi căn cứ tính tiền công.","example":"Làm 8 giờ × đơn giá giờ là theo thời gian; may 20 áo × đơn giá áo là theo sản phẩm."},"103":{"idea":"Montchrestien → thuật ngữ kinh tế chính trị → 1615. Nhớ “tên gọi trước, hệ thống khoa học sau”.","example":"Đặt nhãn sách năm 1615 lên dòng thời gian, trước Adam Smith thế kỷ XVIII; không lấy năm xuất hiện tên gọi làm năm ra đời học thuyết Mác."},"104":{"idea":"Đại hội X nhấn CNH, HĐH gắn kinh tế tri thức: không chỉ thêm máy móc mà nâng hàm lượng hiểu biết.","example":"Một cơ sở nông nghiệp dùng dữ liệu đất và phần mềm tưới để tăng hiệu quả, thay vì chỉ mua thêm máy kéo."},"105":{"idea":"John Kay → con thoi bay, thuộc cải tiến ngành dệt trong cách mạng 1. Gắn tên người với đúng bộ phận.","example":"Hình dung con thoi mang sợi ngang chạy qua khung dệt nhanh hơn; khác máy kéo sợi và máy hơi nước."},"106":{"idea":"Các trình độ đan xen: sản xuất nhỏ, thị trường sơ khai và hiện đại cùng tồn tại.","example":"Cùng một thành phố có hàng rong, chợ truyền thống và sàn thương mại điện tử; không phải toàn nền kinh tế cùng ở một nấc."},"107":{"idea":"Nhớ tiến trình mở rộng: khu vực Đông Nam Á → liên khu vực/Châu Á–Thái Bình Dương → thế giới.","example":"ASEAN/AFTA gắn khu vực, ASEM Á–Âu, APEC Châu Á–Thái Bình Dương, WTO toàn cầu. Đây là các cơ chế/tổ chức khác nhau, không cùng một loại hình pháp lý."},"108":{"idea":"Công nghiệp hóa Anh khởi đầu ngành dệt, thuộc công nghiệp nhẹ. Hai mức trả lời khác độ cụ thể nhưng cùng hướng.","example":"Quần áo có nhu cầu lớn, kéo sợi và dệt dễ thấy tác dụng cơ giới hóa; đừng chọn luyện thép làm ngành khởi đầu câu này."},"109":{"idea":"Tỷ suất m′ = m/v phản ánh mức độ; khối lượng M phản ánh quy mô. Nhớ “phần trăm” khác “bao nhiêu tiền”.","example":"Hai xưởng đều m′ = 100%, nhưng xưởng thuê nhiều người có thể thu m lớn hơn; mức độ bằng nhau không có nghĩa quy mô bằng nhau."},"110":{"idea":"Cartel phổ biến ở châu Âu cuối thế kỷ XIX, gắn quá trình chuyển sang độc quyền.","example":"Hình dung nhiều xưởng vẫn độc lập nhưng bắt tay thống nhất giá/sản lượng, trong bối cảnh doanh nghiệp đã lớn lên qua cạnh tranh."},"111":{"idea":"Dịch vụ thường được tạo và tiêu dùng đồng thời, khó cất trữ như hàng vật chất. Nên hiểu đặc điểm này cho dịch vụ điển hình.","example":"Một giờ cắt tóc hôm nay không thể đóng hộp để bán nguyên giờ dịch vụ đó ngày mai; chiếc kéo thì có thể lưu kho."},"112":{"idea":"Năng suất tác động giá trị đơn vị theo chiều ngược; cường độ chủ yếu tăng tổng lao động và tổng sản phẩm, khi các điều kiện khác giữ nguyên.","example":"Máy tốt giúp 1 giờ làm gấp đôi áo → giá trị mỗi áo giảm. Chỉ làm gấp sức tạo gấp đôi lượng lao động thì giá trị đơn vị không tự giảm."},"113":{"idea":"Tham dự là kiểm soát qua cổ phần; ủy nhiệm là dùng quyền đại diện được giao. Kết hợp giúp chi phối lượng vốn lớn hơn vốn trực tiếp nắm.","example":"Người nắm cổ phần công ty mẹ còn nhận quyền biểu quyết từ cổ đông khác, rồi công ty mẹ chi phối công ty con."},"114":{"idea":"Câu nhận định về vai trò nổi bật của kinh tế tri thức gắn Đại hội IX (2001) theo trích dẫn PDF; X nhấn gắn với CNH.","example":"Ghi hai thẻ cạnh nhau: IX “nhận định xu hướng”, X “gắn CNH với tri thức”; phân biệt nội dung thay vì đoán số đại hội."},"115":{"idea":"Độc quyền ở đây là liên minh doanh nghiệp lớn đủ sức chi phối sản xuất, tiêu thụ, giá cả để thu lợi nhuận cao.","example":"Một nhóm hãng kiểm soát phần lớn nguồn cung và phối hợp giá có quyền lực khác hẳn vài cửa hàng nhỏ tình cờ bán cùng giá."},"116":{"idea":"Cổ điển Anh tìm các quy luật khách quan của kinh tế, thay vì xem kinh tế chỉ là quyết định tùy ý của người cầm quyền.","example":"Giá cao thu hút nguồn cung dù người bán không hẹn nhau: dùng hình ảnh này để nhớ tư tưởng trật tự kinh tế có quy luật."},"117":{"idea":"Đề hỏi lý do phải HOÀN THIỆN: vì còn thiếu, chưa đồng bộ, chưa hiệu quả. Sự lãnh đạo của Đảng là đặc điểm, không thay thế lý do đó.","example":"Xe cần sửa vì phanh chưa tốt, không phải vì có người lái; tương tự, phân biệt “ai lãnh đạo” với “điểm nào còn thiếu”."},"118":{"idea":"Kinh tế thị trường là phương thức tổ chức kinh tế có thể tồn tại trong các chế độ xã hội khác nhau; không tự nó đối lập mọi chế độ.","example":"Mua bán, giá cả và cạnh tranh có thể được vận dụng trong những hệ thống sở hữu/quản lý khác nhau."},"119":{"idea":"Câu trích dẫn này gắn Đại hội XI (2011) theo PDF. Tách mốc trích dẫn cụ thể khỏi mốc IX (2001) xác định mô hình.","example":"Lập hai nhãn: IX “mô hình tổng quát”; XI “câu mô tả nhiều thành phần, cơ chế thị trường, quản lý nhà nước”."},"120":{"idea":"Tích lũy làm vốn lớn dần; cùng cạnh tranh và tập trung, tạo cơ sở cho độc quyền. Không phải một lần tái đầu tư là thành độc quyền ngay.","example":"Xưởng dùng lãi mở rộng nhiều năm, mua thêm đối thủ rồi đủ sức chi phối ngành: nhớ cả quá trình lớn lên."},"121":{"idea":"Bộ môn sử dụng bốn cuộc cách mạng: hơi nước–điện–máy tính–kết nối thông minh.","example":"Đi một vòng nhà máy tưởng tượng: máy hơi nước, dây chuyền điện, máy điều khiển số, hệ thống cảm biến và AI."},"122":{"idea":"Bộ ba số cốt lõi: IoT thu/kết nối dữ liệu; Big Data xử lý dữ liệu lớn; AI phân tích, dự đoán, quyết định.","example":"Vườn thông minh: cảm biến đo ẩm → kho dữ liệu mùa vụ → AI gợi ý tưới. Nhớ ba vai trò, không chỉ ba chữ viết tắt."},"123":{"idea":"Cách mạng 3 gắn điện tử, máy tính và tự động hóa bằng CNTT. Gọi tắt cách mạng máy tính.","example":"Máy CNC chạy theo chương trình là hình ảnh gần hơn máy hơi nước; kết nối thông minh toàn hệ thống nhấn mạnh hơn ở lần 4."},"124":{"idea":"Đối tượng là quan hệ giữa người với người trong sản xuất và trao đổi, gắn lực lượng sản xuất và kiến trúc thượng tầng.","example":"Cùng một dây chuyền, môn này hỏi ai sở hữu, ai làm thuê, ai hưởng phần thu nhập; không chủ yếu hỏi sơ đồ mạch của máy."},"125":{"idea":"Đối tượng là quan hệ giữa người với người trong sản xuất và trao đổi, gắn lực lượng sản xuất và kiến trúc thượng tầng.","example":"Cùng một dây chuyền, môn này hỏi ai sở hữu, ai làm thuê, ai hưởng phần thu nhập; không chủ yếu hỏi sơ đồ mạch của máy."},"126":{"idea":"Bốn tên chức năng trong chương trình: nhận thức, thực tiễn, tư tưởng, phương pháp luận. “Giáo dục” không phải tên mục độc lập ở đây.","example":"Một bài học vẫn có tác dụng giáo dục, nhưng khi thi theo danh mục phải phân biệt tác dụng rộng với bốn chức năng được gọi tên."},"127":{"idea":"Ứng dụng khoa học công nghệ cần gắn kinh tế tri thức: biết tạo, tiếp thu và sử dụng tri thức để tăng năng suất.","example":"Mua máy hiện đại nhưng không đào tạo người vận hành sẽ khó hiệu quả; kiến thức và máy móc cần đi cùng nhau."},"128":{"idea":"Năm chức năng: đo giá trị, lưu thông, thanh toán, cất trữ, tiền tệ thế giới. Nhớ “Đo–Mua–Trả–Giữ–Ngoài”.","example":"Xem bảng giá → trả tiền mua ngay → trả nợ → để dành → thanh toán quốc tế: năm tình huống tương ứng, trong mô hình tiền tệ của giáo trình."},"129":{"idea":"William Petty gắn vai trò sáng lập cổ điển Anh; Adam Smith gắn hệ thống hóa khoa học. Nhớ “Petty mở, Smith xây”.","example":"Dùng hình ảnh người đặt viên móng và người dựng ngôi nhà để phân biệt hai câu dễ nhầm về lịch sử học thuyết."},"130":{"idea":"Hàng hóa được làm ra để trao đổi/mua bán, không chỉ vì có ích.","example":"Bánh nướng để gia đình ăn là sản phẩm; cùng loại bánh nướng để bán ở quầy là hàng hóa."},"131":{"idea":"Khối lượng giá trị thặng dư là lượng m tính bằng tiền; tỷ suất là m so với v. Đơn vị đo giúp phân biệt.","example":"“Thu 30 triệu thặng dư” nói khối lượng; “m′ = 150%” nói tỷ suất. Đừng trả lời tỷ lệ khi đề hỏi lượng tiền."},"132":{"idea":"Tiền thành tư bản khi được vận động nhằm thu giá trị thặng dư. Chỉ có một khoản tiền lớn để yên chưa đủ.","example":"100 triệu giữ trong két vẫn là tiền; dùng vốn mua đầu vào, thuê lao động và sản xuất để tiền trở về lớn hơn là vận động tư bản trong ví dụ."},"133":{"idea":"Máy móc là điều kiện vật chất tăng năng suất và chuyển giá trị cũ; theo Mác, lao động sống mới tạo giá trị mới.","example":"Máy trị giá 100 triệu dùng dần sẽ phân bổ hao mòn vào sản phẩm; không coi toàn bộ tiền bán thêm nhờ máy là giá trị tự máy sinh ra."},"134":{"idea":"Cách mạng công nghiệp thể hiện bước nhảy ở tư liệu lao động, kéo theo thay đổi sản xuất.","example":"Từ búa tay sang máy ép, rồi máy điều khiển số: công cụ thay đổi chất lượng hoạt động, không chỉ đông thêm thợ."},"135":{"idea":"Đại hội VI (1986) → Đổi mới, đổi cơ chế quản lý kinh tế. IX (2001) → xác định mô hình tổng quát.","example":"Hình dung hai cột mốc trên đường: bắt đầu đổi hướng năm 1986, xác định rõ tên mô hình năm 2001."},"136":{"idea":"Lạm phát tác động cả người sản xuất qua chi phí và người tiêu dùng qua sức mua.","example":"Giá bột tăng khiến tiệm bánh tăng chi phí; giá bánh tăng khiến khách cùng số tiền mua ít bánh hơn."},"137":{"idea":"Trong tư liệu lao động, công cụ trực tiếp tác động đối tượng lao động nên quyết định lớn đến năng suất.","example":"Cùng thợ và gỗ, dùng cưa máy thay cưa tay có thể làm nhanh hơn; nhà kho cũng là điều kiện nhưng không tác động trực tiếp như cưa."},"138":{"idea":"Đề thiếu tên vai trò nên chưa thể xác định đáp án chắc chắn: “chủ đạo” khác “động lực quan trọng”.","example":"Trong cách diễn đạt của tài liệu: nhà nước–chủ đạo; tư nhân–một động lực quan trọng. Điền thiếu một từ là có thể đổi đáp án."},"139":{"idea":"Cạnh tranh là các chủ thể giành điều kiện và lợi ích tốt nhất cho mình; không chỉ là hạ giá.","example":"Hai quán cùng cải thiện món ăn, giao hàng nhanh và phục vụ tốt để hút khách: đều là cách cạnh tranh."},"140":{"idea":"Đối tượng là quan hệ giữa người với người trong sản xuất và trao đổi, gắn lực lượng sản xuất và kiến trúc thượng tầng.","example":"Cùng một dây chuyền, môn này hỏi ai sở hữu, ai làm thuê, ai hưởng phần thu nhập; không chủ yếu hỏi sơ đồ mạch của máy."},"141":{"idea":"Giá trị nội tại là cơ sở tỷ lệ trao đổi theo lý luận lao động; tỷ lệ giao dịch thực tế còn có thể dao động.","example":"Nếu áo kết tinh gấp đôi lao động xã hội cần thiết của khăn, tỷ lệ 1 áo/2 khăn minh họa cơ sở giá trị, không cam kết mọi phiên chợ đúng tỷ lệ ấy."},"142":{"idea":"Công nghiệp 4.0 → Đức, 2011. Gắn mốc với sáng kiến về nhà máy kết nối thông minh.","example":"Hình dung các máy “nói chuyện” qua mạng trong một nhà máy Đức; không lấy năm ra đời Internet làm mốc thuật ngữ này."},"143":{"idea":"Công nghiệp hóa Anh khởi đầu ngành dệt, thuộc công nghiệp nhẹ. Hai mức trả lời khác độ cụ thể nhưng cùng hướng.","example":"Quần áo có nhu cầu lớn, kéo sợi và dệt dễ thấy tác dụng cơ giới hóa; đừng chọn luyện thép làm ngành khởi đầu câu này."},"144":{"idea":"Năng suất là hướng bền vững: sản xuất nhiều hơn trên cùng hao phí lao động. Tăng cường độ bị giới hạn bởi sức người.","example":"Cải tiến quy trình giúp gói 200 hộp thay 100 hộp/giờ mà không phải làm gấp đôi sức mỗi ngày."},"145":{"idea":"Tăng trưởng cần con người, công nghệ, vốn, cơ cấu và thể chế. Nhớ “Người–Máy–Vốn–Ngành–Luật”.","example":"Xưởng có máy và tiền vẫn khó tăng trưởng nếu thiếu thợ giỏi, chọn sai sản phẩm hoặc thủ tục làm tắc hoạt động."},"146":{"idea":"“Cách mạng” nhấn thay đổi về chất của lực lượng sản xuất, không chỉ thêm vài thiết bị số.","example":"Một nhà máy tự thu dữ liệu, dự đoán hỏng máy và phối hợp đơn hàng làm thay đổi cách sản xuất, sâu hơn việc mua thêm máy tính văn phòng."},"147":{"idea":"Cách mạng công nghiệp 1 khởi phát ở Anh; dấu nối dễ nhớ là dệt–than–hơi nước.","example":"Hình dung xưởng dệt Anh chuyển từ sức người sang máy móc, rồi tác động lan sang các ngành và nước khác."},"148":{"idea":"PDF chọn Anh cho nơi khởi phát lần 2. Cần nhớ lần 2 còn phát triển mạnh ở nhiều nước như Đức, Mỹ; câu hỏi một quốc gia có tính khái quát.","example":"Dây chuyền điện và sản xuất hàng loạt là dấu nhận diện chắc hơn việc gắn mọi phát minh lần 2 với duy nhất một nước."},"149":{"idea":"Mô hình Liên Xô trong tài liệu gắn đầu những năm 1930, với ưu tiên công nghiệp nặng và kế hoạch hóa.","example":"Hình dung bản kế hoạch xây đồng thời nhà máy thép, điện, chế tạo máy. Không hiểu đây là năm xuất hiện mọi chính sách công nghiệp ở Liên Xô."},"150":{"idea":"Mệnh đề sai là “chỉ phát triển mạnh ở phong kiến”. Thị trường phát triển cao, phổ biến trong chủ nghĩa tư bản và có thể được vận dụng ở chế độ khác.","example":"Từ chợ thủ công đến thị trường tài chính và chuỗi cung ứng hiện đại: thực tế không dừng ở xã hội phong kiến."},"151":{"idea":"Nhà nước có thể hạn chế, khắc phục khuyết tật thị trường; không đồng nghĩa chữa hoàn toàn hoặc luôn thành công.","example":"Thu phí xả thải và kiểm soát ô nhiễm có thể giảm tác hại mà giá hàng hóa chưa phản ánh hết."},"152":{"idea":"Cấu tạo hữu cơ ký hiệu c/v, là cấu tạo giá trị do cấu tạo kỹ thuật quyết định và phản ánh thay đổi kỹ thuật.","example":"Thêm máy trên mỗi lao động thường làm tỷ trọng c tăng so với v; đừng chỉ thấy một tỷ lệ tiền bất kỳ rồi bỏ qua cơ sở kỹ thuật."},"153":{"idea":"Giá trị là cơ sở quyết định giá cả trong lý luận Mác; cung cầu làm giá cả dao động quanh cơ sở ấy.","example":"Sản phẩm cần nhiều lao động xã hội thường có nền giá trị cao hơn, còn đợt khan hàng có thể đẩy giá bán nhất thời lên thêm."},"154":{"idea":"Xuất khẩu tư bản hướng tới thu giá trị thặng dư và nguồn lợi ở nước nhận vốn. Phân biệt mang vốn đi đầu tư với mang hàng đi bán.","example":"Xây nhà máy ở nước ngoài để nhận lợi nhuận là xuất khẩu tư bản; bán lô áo ra nước ngoài là xuất khẩu hàng hóa."},"155":{"idea":"n = thời gian kỳ xét / thời gian một vòng chu chuyển. Đổi về cùng đơn vị trước khi chia.","example":"Một vòng mất 3 tháng, một năm 12 tháng → n = 12/3 = 4 vòng/năm. Không lấy 1 năm chia 3 tháng mà bỏ đổi đơn vị."},"156":{"idea":"Tính tất yếu CNH gắn phát triển lực lượng sản xuất, cơ sở vật chất và rút ngắn khoảng cách. Câu loại “yêu cầu thể chế chính trị” vì không phải căn cứ trực tiếp trong danh mục.","example":"Muốn nâng năng suất nông nghiệp cần máy móc, kỹ năng, hạ tầng; đó là nhu cầu kinh tế khách quan, không chỉ mong muốn chủ quan."},"157":{"idea":"Quy mô lớn giúp tập trung vốn, nhân lực cho nghiên cứu có chi phí cao; đây là một khả năng tích cực của độc quyền.","example":"Một chương trình nghiên cứu vật liệu mới cần phòng thí nghiệm đắt tiền và nhiều năm thử nghiệm; doanh nghiệp lớn có thể huy động nguồn lực đó."},"158":{"idea":"Theo cách diễn đạt của PDF: nhà nước–chủ đạo; tư nhân–một động lực quan trọng. Học đúng phiên bản tài liệu của môn.","example":"Hình dung hạ tầng công then chốt và mạng lưới doanh nghiệp tư nhân đổi mới, tạo việc làm; hai vai trò không có nghĩa mọi đơn vị đều hiệu quả như nhau."},"159":{"idea":"Cạnh tranh làm doanh nghiệp mạnh lớn lên, doanh nghiệp yếu bị loại hoặc sáp nhập; tập trung đến mức cao có thể dẫn tới độc quyền.","example":"Mười hãng cạnh tranh, vài hãng mua lại đối thủ rồi chi phối ngành: độc quyền nảy sinh từ chính quá trình cạnh tranh."},"160":{"idea":"Theo khung phân tích của câu, nhà nước gắn lợi ích các tổ chức độc quyền. Không diễn giải thành mọi quyết định nhà nước đều do một doanh nghiệp ra lệnh.","example":"Nhóm doanh nghiệp lớn tác động chính sách để bảo vệ lợi ích ngành là hình ảnh minh họa sự chi phối lợi ích."},"161":{"idea":"Ba mặt tích cực được hỏi: phát triển lực lượng sản xuất, chuyển sản xuất nhỏ sang hiện đại, xã hội hóa sản xuất.","example":"Một chiếc xe cần nhà máy và mạng lưới hàng nghìn nhà cung cấp thay vì một thợ tự làm mọi chi tiết: quy mô và liên kết cùng tăng."},"162":{"idea":"Quy luật kinh tế có tính khách quan; chính sách do con người đặt ra, muốn hiệu quả phải tính tới quy luật.","example":"Ấn giá quá thấp khi hàng khan hiếm có thể gây thiếu hàng: mục tiêu chính sách không tự xóa quan hệ cung cầu."},"163":{"idea":"Hai cực hình thành cùng nhau: ít người nắm tư liệu sản xuất, nhiều người phải bán sức lao động vì không đủ tư liệu tự sản xuất.","example":"Một bên sở hữu xưởng và máy; bên kia có khả năng làm việc nhưng phải tìm hợp đồng làm thuê để sống."},"164":{"idea":"Sức lao động thành hàng hóa phổ biến trong sản xuất hàng hóa tư bản chủ nghĩa, khi làm thuê là quan hệ rộng khắp.","example":"Người lao động bán khả năng làm việc theo thời gian cho chủ xưởng; không phải bán đứt con người mình như một vật sở hữu."},"165":{"idea":"Theo tổ chức tham gia xã hội: thể chế công và thể chế tư. Xét chủ thể tổ chức, không nhầm với lĩnh vực kinh tế hay văn hóa.","example":"Quy trình cơ quan hành chính thuộc phía công; điều lệ, quy tắc quản trị một tổ chức tư thuộc phía tư."},"166":{"idea":"Bộ công cụ vĩ mô gồm luật, kế hoạch gắn thị trường, tài chính–tiền tệ và đối ngoại. Nhớ nhiều cần điều khiển cùng một nền kinh tế.","example":"Thuế, chi đầu tư công, lãi suất và chính sách thương mại tác động theo cách khác nhau; không công cụ nào thay thế toàn bộ số còn lại."},"167":{"idea":"Xuất khẩu tư bản nổi bật ở giai đoạn độc quyền; xuất khẩu hàng hóa nổi bật ở giai đoạn tự do cạnh tranh. Đây là đặc điểm, không phải chỉ tồn tại duy nhất ở một giai đoạn.","example":"Mang vốn xây xưởng ở nước ngoài khác việc sản xuất trong nước rồi xuất áo sang bán."},"168":{"idea":"Năm chức năng: đo giá trị, lưu thông, thanh toán, cất trữ, tiền tệ thế giới. Nhớ “Đo–Mua–Trả–Giữ–Ngoài”.","example":"Xem bảng giá → trả tiền mua ngay → trả nợ → để dành → thanh toán quốc tế: năm tình huống tương ứng, trong mô hình tiền tệ của giáo trình."},"169":{"idea":"Thể chế gồm luật chơi, bộ máy và cách vận hành; không chỉ một tập văn bản luật.","example":"Kinh doanh cần quy định đăng ký, cơ quan tiếp nhận và quy trình xử lý hồ sơ. Có luật mà không có thực thi vẫn chưa đủ."},"170":{"idea":"Giai đoạn 1: tiền mua tư liệu sản xuất và sức lao động → hình thái tư bản tiền tệ.","example":"Chủ tiệm dùng tiền mua lò, bột và thuê thợ; tiền đang chuyển thành các đầu vào sản xuất."},"171":{"idea":"Giai đoạn 2 là SẢN XUẤT, tư bản ở hình thái sản xuất. Chữ “lưu thông” lặp trong đề là lỗi diễn đạt.","example":"Bột và sức lao động đang được dùng làm bánh trong lò: chưa phải khâu mua đầu vào hay bán bánh."},"172":{"idea":"Giai đoạn 3: hàng hóa chứa giá trị thặng dư được bán để thu tiền → tư bản hàng hóa.","example":"Bánh hoàn thành chờ bán, sau đó doanh thu quay về: tư bản đang từ H′ chuyển thành T′."},"173":{"idea":"Cố định/lưu động phân theo cách chuyển giá trị vào sản phẩm: từng phần hay toàn bộ trong một chu kỳ.","example":"Lò bánh dùng nhiều năm, giá trị chuyển dần; bột dùng hết trong mẻ, giá trị chuyển toàn bộ. Không phân theo “có di chuyển được hay không”."},"174":{"idea":"Cách mạng 3: đầu thập niên 1960 đến cuối thế kỷ XX theo giáo trình. Móc nhớ máy tính–điện tử–tự động hóa.","example":"Hình dung máy tính điều khiển máy công cụ, trước giai đoạn mạng cảm biến và dữ liệu lớn của lần 4."},"175":{"idea":"Khi tỷ lệ dành m để tích lũy đã cho, quy mô tích lũy phụ thuộc m′, năng suất, phần vốn sử dụng chưa tiêu dùng hết và vốn ứng trước.","example":"Máy còn dùng được nhiều năm, năng suất tốt, vốn lớn làm khả năng mở rộng khác xưởng nhỏ dù cùng dành 50% thặng dư để tái đầu tư."},"176":{"idea":"Độc lập tự chủ nghĩa là có năng lực tự quyết và nền tảng trong nước; hội nhập vẫn cần thiết.","example":"Một ngành dùng linh kiện nhập khẩu nhưng có kỹ sư, công nghệ cốt lõi và nguồn cung thay thế sẽ chống chịu tốt hơn khi đối tác ngừng bán."},"177":{"idea":"Trao đổi hàng hóa mở rộng cần một vật ngang giá chung; nhu cầu ấy thúc đẩy tiền ra đời.","example":"Người có cá muốn gạo nhưng người có gạo lại cần vải: tiền giúp không phải chờ hai nhu cầu trùng khớp trực tiếp."},"178":{"idea":"Liên kết ngang = cùng ngành/cùng tầng sản xuất; liên kết dọc = khác khâu trong chuỗi.","example":"Hai hãng sữa sáp nhập là ngang; hãng sữa gắn với trang trại và cửa hàng phân phối là dọc."},"179":{"idea":"Mua sức lao động tạo điều kiện; dùng sức lao động trong sản xuất mới tạo giá trị thặng dư. Không phải hành vi mua tự sinh m.","example":"Thuê thợ với giá trị sức lao động 200, thợ tạo 350 giá trị mới: phần 150 xuất hiện trong quá trình lao động."},"180":{"idea":"Câu muốn phân biệt đặc điểm giai đoạn: tự do cạnh tranh nổi bật xuất khẩu hàng hóa, độc quyền nổi bật xuất khẩu tư bản.","example":"Chở vải sản xuất trong nước đi bán là hàng hóa; mang vốn ra nước ngoài mở nhà máy vải là tư bản."},"181":{"idea":"Tích lũy tư bản = biến một phần giá trị thặng dư thành vốn mới. Nhớ “dư → vốn”, không phải toàn bộ tiền kiếm được đều tích lũy.","example":"Thu 100 thặng dư, dùng 60 mua thêm máy/thuê lao động, 40 tiêu dùng cá nhân: chỉ 60 được tư bản hóa."},"182":{"idea":"Nguồn lý luận kinh tế trực tiếp là cổ điển Anh; Mác kế thừa có phê phán rồi phát triển học thuyết của mình.","example":"Hình dung tiếp nhận nền tảng giá trị lao động từ Petty–Smith–Ricardo rồi phát triển phân tích lao động hai mặt và giá trị thặng dư."},"183":{"idea":"Nguồn chính của lợi nhuận độc quyền vẫn là lao động tạo giá trị thặng dư; quyền lực giá giúp thu thêm phần phân phối lại.","example":"Một tập đoàn có công nhân sản xuất tạo m, đồng thời có thể ép giá nhà cung cấp; không xem giá độc quyền tự tạo ra giá trị mới."},"184":{"idea":"T–H–T′ bắt đầu bằng tiền, kết thúc bằng tiền lớn hơn; mục đích là tăng giá trị. H–T–H nhằm có vật để dùng.","example":"Mua hàng 100, bán 120 minh họa hình thức vận động; riêng việc mua rẻ bán đắt chưa giải thích nguồn m của toàn xã hội."},"185":{"idea":"p′ = m/(c+v) nhỏ hơn m′ = m/v khi c > 0 và m > 0, vì mẫu số lớn hơn.","example":"c=80, v=20, m=20 → p′=20%, m′=100%. So cùng m sẽ thấy ngay vì sao hai tỷ suất khác nhau."},"186":{"idea":"Bốn nấc hình thái giá trị: đổi đơn lẻ → nhiều hàng → vật ngang giá chung → tiền tệ.","example":"1 áo đổi gạo; áo đổi nhiều thứ; mọi thứ đổi qua một vật chung; vai trò ấy cố định ở tiền. Hình dung độ thuận tiện tăng dần."},"187":{"idea":"Cách mạng 1 chuyển từ thủ công sang máy móc, gắn động lực hơi nước.","example":"Người thợ không còn tự kéo từng động tác khung dệt, máy cơ khí đảm nhận phần việc lớn; đây là thay đổi công cụ và cách sản xuất."},"188":{"idea":"Chủ thể thị trường có quyền tự chủ và tự chịu kết quả: tự quyết sản xuất, kinh doanh, lời/lỗ.","example":"Chủ quán chọn món và giá; nếu khách không mua, chủ quán phải chịu lỗ. Có tự chủ cũng phải tuân thủ pháp luật."},"189":{"idea":"Đề mô tả tiền có sức mua vượt xa giá trị vật liệu làm ra nó; khóa “tiền vàng” có dấu hiệu sai. Cần đối chiếu tiền pháp định/tiền dấu hiệu.","example":"Tờ tiền có mệnh giá lớn dù giấy và mực rẻ là ví dụ phù hợp mô tả; vàng lại có giá trị vật liệu đáng kể."},"190":{"idea":"Cả tuyệt đối lẫn tương đối đều tăng tỷ lệ m/v; khác nhau ở cách thay đổi thời gian lao động.","example":"4 tất yếu + 4 dư có m′=100%; kéo thành 4+6 cho 150%; giữ 8 giờ, chia thành 3+5 cho khoảng 166,7%."},"191":{"idea":"Nhà nước thường đảm nhận hạ tầng vốn lớn, thu hồi chậm, lợi nhuận trực tiếp thấp vì tư nhân ít muốn tự gánh.","example":"Đường sắt, hệ thống thoát nước có lợi ích rộng cho nền kinh tế nhưng cần vốn lớn và chờ lâu mới thu hồi."},"192":{"idea":"M = m′ × V; tỷ suất phần trăm phải đổi thành hệ số. V là tổng vốn khả biến.","example":"m′=200%, V=50 triệu → M=2×50=100 triệu, không phải 200×50."},"193":{"idea":"Sản xuất hàng hóa hướng sản phẩm ra trao đổi, mua bán để đáp ứng nhu cầu xã hội.","example":"Vườn rau trồng cho nhà ăn khác trang trại trồng theo đơn siêu thị; nhìn mục đích sản xuất chứ không chỉ hình dạng sản phẩm."},"194":{"idea":"Theo tư duy Đổi mới, cơ chế thị trường có thể được sử dụng để xây dựng CNXH; thị trường không thuộc riêng một chế độ.","example":"Giá cả giúp doanh nghiệp biết hàng nào được cần, trong khi nhà nước vẫn định hướng và thực hiện mục tiêu xã hội."},"195":{"idea":"Tích lũy tư bản = biến một phần giá trị thặng dư thành vốn mới. Nhớ “dư → vốn”, không phải toàn bộ tiền kiếm được đều tích lũy.","example":"Thu 100 thặng dư, dùng 60 mua thêm máy/thuê lao động, 40 tiêu dùng cá nhân: chỉ 60 được tư bản hóa."},"196":{"idea":"Câu trích “dân là gốc” trong đề gắn Đại hội XII. Không suy ra tư tưởng này chỉ xuất hiện lần đầu ở XII.","example":"Hình dung người dân vừa là người hưởng lợi, vừa tham gia góp ý và thực hiện đổi mới: ba vai trò giúp nhớ nội dung câu trích."},"197":{"idea":"Ba câu hỏi cơ bản: làm gì, làm bằng cách nào, ai được dùng. Nhớ “Sản phẩm–Phương pháp–Người hưởng”.","example":"Quán ăn chọn bán bún, nấu thủ công hay dùng máy, phục vụ nhóm khách nào: ba quyết định kinh tế cụ thể."},"198":{"idea":"Xuất khẩu tư bản là đưa vốn ra nước ngoài đầu tư để thu lợi; không phải chỉ chuyển hàng qua biên giới.","example":"Góp vốn mở xưởng ở nước ngoài tạo quyền hưởng lợi nhuận từ hoạt động ở đó; gửi lô hàng bán cho khách là xuất khẩu hàng hóa."},"199":{"idea":"Các lao động tư nhân độc lập gặp nhau trên thị trường thông qua sản phẩm hàng hóa; trao đổi xác nhận tính xã hội của lao động.","example":"Hai hộ chuyên làm gốm và dệt vải mua bán với nhau; sản phẩm nội bộ giữa hai bộ phận cùng xưởng chưa tự thành giao dịch thị trường."},"200":{"idea":"Phân biệt theo quy mô lặp lại: giữ nguyên là giản đơn; lớn hơn là mở rộng.","example":"Năm trước làm 1.000 áo, năm sau lặp lại 1.000 là giản đơn; đầu tư thêm để làm 1.500 là mở rộng, nếu xét cùng điều kiện so sánh."},"201":{"idea":"Câu trích nói sức phát triển của lực lượng sản xuất, tức năng lực làm ra của cải vật chất.","example":"Hình dung máy hơi nước, đường sắt, nhà máy làm sản lượng tăng vượt sản xuất thủ công trước đó; chỗ trống không phải “quan hệ sản xuất”."},"202":{"idea":"Cạnh tranh buộc người sản xuất năng động, nhạy nhu cầu và đổi mới để tồn tại.","example":"Quán bún mất khách khi phục vụ chậm phải cải tiến món và quy trình; không thể chỉ dựa vào việc đã mở quán trước."},"203":{"idea":"Lợi nhuận một doanh nghiệp có thể lệch m do giá bán khác giá trị; xét toàn xã hội trong mô hình, tổng p = tổng m.","example":"Hàng giá trị 120, chi phí 100: bán 125 thì p=25, bán 115 thì p=15, dù m trong hàng là 20."},"204":{"idea":"Cả năng suất và cường độ tăng đều làm nhiều sản phẩm hơn trong cùng thời gian; nguyên nhân và tác động giá trị khác nhau.","example":"Máy tốt hơn hoặc người làm gấp sức đều có thể tăng từ 10 lên 20 món/giờ. Chỉ nhìn số món chưa xác định được cách nào."},"205":{"idea":"Ba hạn chế đề liệt kê: lợi ích thiểu số, xung đột/chiến tranh, phân hóa giàu nghèo. Học như khung đánh giá của môn, không quy mọi sự kiện cho một nguyên nhân.","example":"Sản lượng có thể tăng mà thành quả phân phối không đều; tăng của cải và công bằng phân phối là hai câu hỏi khác nhau."},"206":{"idea":"Không phải mọi sản phẩm là hàng hóa: cần mục đích trao đổi/mua bán. Chữ “mọi” làm mệnh đề sai.","example":"Rau nhà trồng để ăn là sản phẩm có ích nhưng không phải hàng hóa trong tình huống đó; mang trồng để bán mới khác."},"207":{"idea":"Chi phí lao động xã hội gồm lao động quá khứ trong tư liệu sản xuất và lao động sống mới hao phí: c + v + m.","example":"Chiếc áo chứa giá trị vải/máy chuyển vào, cộng giá trị mới do người may tạo ra. Đừng chỉ cộng các khoản chủ trả tiền."},"208":{"idea":"Khóa A đáng nghi: tư bản giàu lên và mâu thuẫn tăng không rõ vì sao là ý sai. Không học ngược rằng tích lũy không làm giàu chủ tư bản.","example":"Xưởng tái đầu tư m có thể tăng máy, vốn và chênh lệch tài sản; cần đối chiếu câu gốc để xác định lựa chọn sai hợp lý."},"209":{"idea":"Giá trị cá biệt dựa vào hao phí của chính người sản xuất; giá trị xã hội dựa vào mức xã hội cần thiết.","example":"Xưởng A may áo 1 giờ, B 2 giờ: hao phí cá biệt khác nhau; thị trường không tự trả gấp đôi chỉ vì B làm chậm."},"210":{"idea":"Ngang giá là nguyên tắc trên cơ sở giá trị; giá cả thực tế vẫn có thể lên xuống quanh giá trị.","example":"Một món giá trị 100 có lúc bán 95, lúc 105 do cung cầu. Đừng hiểu ngang giá là mọi giao dịch luôn đúng một mức cố định."},"211":{"idea":"Mâu thuẫn cơ bản: sản xuất ngày càng mang tính xã hội nhưng chiếm hữu mang tính tư nhân tư bản chủ nghĩa.","example":"Hàng nghìn người và nhà cung cấp cùng làm một sản phẩm, còn quyền định đoạt lợi nhuận tập trung ở chủ sở hữu vốn."},"212":{"idea":"Phổ biến: có giá cả, cạnh tranh, cung cầu. Đặc thù: mục tiêu, sở hữu, phân phối và quản lý theo định hướng XHCN.","example":"Cửa hàng vẫn phản ứng với nhu cầu khách, đồng thời nền kinh tế có chính sách an sinh và định hướng phát triển của mình."},"213":{"idea":"Theo lĩnh vực cốt lõi, nhớ chính trị–kinh tế–xã hội. Đừng lẫn với phân loại công/tư theo tổ chức.","example":"Quy tắc bầu cử, quy tắc thị trường và chính sách quan hệ xã hội minh họa ba nhóm lĩnh vực khác nhau."},"214":{"idea":"Chi phí tư bản k = c+v; giá trị hàng hóa = c+v+m. Khi m>0, k nhỏ hơn giá trị.","example":"c=80, v=20, m=20: nhà tư bản ứng 100 nhưng hàng có giá trị 120; phần chênh là m."},"215":{"idea":"Tích lũy nguyên thủy tạo hai điều kiện ban đầu: tập trung tư liệu/tiền và người lao động mất tư liệu, phải làm thuê.","example":"Hình dung đất và công cụ tập trung vào ít người, còn nhiều người rời sản xuất tự chủ để tìm việc ở xưởng."},"216":{"idea":"Bốn nguyên nhân độc quyền nhà nước: tập trung vốn, phân công xã hội, mâu thuẫn xã hội, quốc tế hóa/cạnh tranh.","example":"Một dự án giao thông xuyên vùng đòi vốn lớn, phối hợp ngành, xử lý lợi ích dân cư và sức cạnh tranh: bốn loại sức ép gợi bốn nguyên nhân."},"217":{"idea":"c là giá trị cũ của tư liệu sản xuất đã tiêu dùng, được chuyển sang sản phẩm; v+m là giá trị mới.","example":"Làm bánh dùng bột 40, hao mòn lò 10: c chuyển vào mẻ là 50, không phải toàn bộ giá mua chiếc lò."},"218":{"idea":"Trả đúng giá trị sức lao động vẫn có m vì giá trị sử dụng của sức lao động tạo giá trị mới lớn hơn chính nó.","example":"Tiền công tương ứng 4 giờ tất yếu, ngày làm 8 giờ: 4 giờ còn lại tạo m, dù không mua sức lao động dưới giá trị."},"219":{"idea":"Hai giai đoạn phát triển chính được hỏi: tự do cạnh tranh rồi độc quyền. Độc quyền nhà nước là sự phát triển của giai đoạn sau.","example":"Hình dung nhiều hãng cạnh tranh, sau đó vốn tập trung vào vài tập đoàn; cạnh tranh vẫn tiếp tục dưới hình thức mới."},"220":{"idea":"Lênin gắn chuỗi “cạnh tranh → tập trung → độc quyền”. Nhớ tác giả qua nội dung phân tích giai đoạn độc quyền.","example":"Nhiều xưởng đua nhau, xưởng mạnh mua xưởng yếu, cuối cùng vài hãng chi phối: chính ví dụ chuỗi này giúp nhớ câu trích."},"221":{"idea":"Tiền trở thành tư bản khi vận động nhằm mang lại giá trị thặng dư; số tiền lớn hay nhỏ không tự quyết định bản chất.","example":"Tiền mua cơm để ăn phục vụ tiêu dùng; tiền ứng vào hoạt động sản xuất để trở về lớn hơn mang mục đích tư bản."},"222":{"idea":"Ba ý đúng mô tả mục tiêu định hướng XHCN; phát triển lực lượng sản xuất tự nó không phải mục tiêu chỉ riêng mô hình này có.","example":"Nhà máy hiện đại nâng năng suất; điểm định hướng còn nằm ở xây nền vật chất và nâng đời sống rộng rãi, công bằng, dân chủ."},"223":{"idea":"Mục đích trực tiếp của sản xuất tư bản chủ nghĩa là giá trị thặng dư ngày càng lớn. Công dụng hàng hóa là điều kiện để bán được.","example":"Chủ xưởng chọn sản xuất áo vì kỳ vọng thu phần giá trị tăng thêm; áo vẫn phải có người cần thì mới thực hiện được mục đích."},"224":{"idea":"Hai loại cơ bản: chênh lệch do lợi thế ruộng/đầu tư; tuyệt đối gắn độc quyền sở hữu đất.","example":"Ruộng tốt có phần chênh lệch so với ruộng xấu; cả người thuê ruộng xấu vẫn phải trả khoản tô cho chủ đất."},"225":{"idea":"Độc quyền nhà nước phục vụ lợi ích tổ chức độc quyền và duy trì hệ thống tư bản chủ nghĩa.","example":"Nhà nước hỗ trợ một ngành lớn khi khủng hoảng vừa bảo vệ doanh nghiệp chi phối vừa giúp hệ thống tránh đổ vỡ dây chuyền."},"226":{"idea":"“Công ty cổ phần” là phép ví trong tài liệu về ảnh hưởng của các nhóm lợi ích; không phải khẳng định nghị viện là công ty về pháp lý.","example":"Hình dung nhiều nhóm có mức ảnh hưởng khác nhau lên quyết định chung, giống cách quyền biểu quyết có trọng lượng khác nhau trong công ty."},"227":{"idea":"Cạnh tranh giữa ngành làm tỷ suất lợi nhuận có xu hướng bình quân. Phân biệt với cạnh tranh nội bộ ngành hình thành giá trị thị trường.","example":"Vốn chuyển từ ngành lợi nhuận thấp sang cao; cung ngành cao tăng, lợi nhuận bị kéo xuống, tạo xu hướng san bằng."},"228":{"idea":"Hai hình thức cơ bản tính tiền công: theo thời gian và theo sản phẩm.","example":"Lương theo giờ/ca thuộc thời gian; lương căn cứ số áo đạt chuẩn thuộc sản phẩm. Tiền mặt/chuyển khoản là cách trả, không phải cách tính."},"229":{"idea":"Câu này đang phân biệt phương tiện trả: tiền hoặc hiện vật. Đừng lẫn với hai hình thức tính tiền công: thời gian/sản phẩm.","example":"Trả một phần thù lao bằng gạo nói thứ được nhận; trả theo số áo may xong nói căn cứ tính lương. Hai tiêu chí khác nhau."},"230":{"idea":"Năng suất tăng nhờ kỹ thuật/kỹ năng làm giá trị đơn vị giảm; cường độ tăng là hao phí nhiều sức hơn, giá trị đơn vị không đổi trong giả định chuẩn.","example":"Làm 20 áo thay 10 nhờ máy tốt khác làm 20 vì gắng sức gấp đôi: cùng sản lượng nhưng khác lượng lao động cho mỗi áo."},"231":{"idea":"Ba hình thái thống nhất: tiền tệ → sản xuất → hàng hóa. Dòng vận động là mua đầu vào → làm ra hàng → bán hàng.","example":"Quán bánh có tiền mua bột, bột đang nướng và bánh chờ bán; nếu một khâu nghẽn, vòng vốn bị gián đoạn."},"232":{"idea":"Tiền công sản phẩm căn cứ số lượng và chất lượng sản phẩm đạt yêu cầu, thực chất là biến tướng của tiền công thời gian.","example":"Đơn giá 20.000/áo đạt chuẩn, may 15 áo thì 300.000; áo lỗi có thể không được tính theo quy định hợp đồng."},"233":{"idea":"Sản phẩm thặng dư là phần vượt nhu cầu tái sản xuất cần thiết, tạo khả năng mở rộng và phát triển xã hội.","example":"Làng làm ra đủ lương thực để sống và còn dư để nuôi người xây đường, nghiên cứu, dạy học; phần dư mở ra khả năng đó."},"234":{"idea":"c và v là các bộ phận của tư bản sản xuất: tư liệu sản xuất và giá trị sức lao động được đưa vào sản xuất.","example":"Trong xưởng may, máy/vải thuộc c, vốn mua sức lao động thuộc v. Đây không phải phân loại tiền đang gửi hay hàng đang chờ bán."},"235":{"idea":"Danh nghĩa và thực tế là hai cách nhìn tiền công: số tiền nhận và sức mua. Đề gọi “hai hình thức” dễ lẫn với thời gian/sản phẩm.","example":"Lương 10 triệu là danh nghĩa; mua được bao nhiêu gạo, dịch vụ mới là thực tế. Không dùng cặp này thay cho cách tính lương khi đề hỏi khác."},"236":{"idea":"Lao động cụ thể có nghề, mục đích, công cụ, thao tác và sản phẩm riêng; tạo giá trị sử dụng.","example":"Thợ mộc dùng cưa làm bàn, thợ may dùng kim làm áo: khác công việc có ích và khác công dụng sản phẩm."},"237":{"idea":"Khan hiếm so với nhu cầu có thể đẩy GIÁ CẢ lên. Không tự suy ra giá trị lao động của món hàng cũng tăng.","example":"Vé một sự kiện hết nhanh có giá bán lại cao; điều đó không chứng minh hao phí lao động sản xuất vé đã tăng tương ứng."},"238":{"idea":"Sơ đồ khái quát: cộng sản nguyên thủy → nô lệ → phong kiến → tư bản → cộng sản chủ nghĩa. Phương án D bị cụt phần cuối.","example":"Dùng năm ô thời gian để nhớ trình tự lý luận; không suy ra lịch sử mọi quốc gia đều trải qua đủ từng ô giống nhau."},"239":{"idea":"Phân công + tách biệt kinh tế do sở hữu/quyền chi phối tạo điều kiện sản xuất hàng hóa.","example":"Người trồng lúa và người làm gốm chuyên việc khác nhau, sản phẩm thuộc chủ khác nhau nên phải trao đổi."},"240":{"idea":"Giá trị sức lao động đo gián tiếp qua tư liệu sinh hoạt cần để tái sản xuất sức lao động, còn gồm đào tạo và duy trì gia đình theo lý luận.","example":"Ăn, ở, phục hồi sức khỏe và học nghề giúp người lao động tiếp tục làm việc; không đo giá trị sức lao động chỉ bằng cân nặng hay số giờ đứng máy."},"241":{"idea":"Mâu thuẫn tư nhân–xã hội: tự quyết làm hàng, nhưng xã hội phải chấp nhận qua mua bán.","example":"Bạn tự may 100 áo theo mẫu mình thích; không ai mua thì lao động tư nhân chưa được thị trường thừa nhận là lao động xã hội cần thiết."},"242":{"idea":"Cơ sở chung là lao động kết tinh; tỷ lệ ngang giá so tổng lượng lao động xã hội cần thiết trong hai lượng hàng đem đổi.","example":"1 áo có thể đổi 2 khăn khi tổng giá trị bằng nhau; không bắt buộc giá trị của từng chiếc áo và từng chiếc khăn phải bằng nhau."},"243":{"idea":"Mác bắt đầu từ hàng hóa, “tế bào” kinh tế phổ biến, rồi phát triển phân tích tiền và tư bản.","example":"Muốn hiểu một nhà máy lớn, trước hết xem sản phẩm được làm để bán có công dụng và giá trị thế nào; đi từ đơn giản đến phức tạp."},"244":{"idea":"Hao phí cá biệt thấp hơn mức xã hội giúp có lợi thế: làm rẻ hơn chuẩn nhưng bán theo mặt bằng thị trường.","example":"Thị trường chấp nhận 2 giờ/áo, xưởng bạn chỉ cần 1,5 giờ nhờ quy trình tốt; bạn có khoảng lợi thế so với người làm chậm."},"245":{"idea":"Giá trị sử dụng đặc biệt của sức lao động là tạo giá trị mới lớn hơn giá trị bản thân nó.","example":"Trả công tương ứng 4 giờ tất yếu, sử dụng ngày 8 giờ: phần lao động còn lại tạo giá trị thặng dư trong mô hình."},"246":{"idea":"Định nghĩa đúng cần nói chuyên môn hóa lao động xã hội thành các ngành/nghề. Khóa PDF lại nói nguyên nhân độc quyền nên không khớp câu hỏi.","example":"Người chuyên trồng lúa, người dệt, người vận tải là phân công lao động xã hội; không phải bản thân định nghĩa đã là “độc quyền”."},"247":{"idea":"Điểm chung: dựa trên hao phí lao động xã hội cần thiết. Điều kiện xác định mức điều tiết có thể khác giữa công nghiệp và nông nghiệp.","example":"Làm chậm cá biệt không khiến xã hội mặc nhiên trả cao hơn, dù sản phẩm là áo hay lúa; đừng đồng nhất chi phí của mọi người."},"248":{"idea":"Chi phí nhà tư bản ứng ra là c+v: tư liệu sản xuất và sức lao động. m là phần tăng thêm, không phải khoản ứng trước đó.","example":"80 nguyên liệu/hao mòn + 20 tiền công = 100 chi phí; nếu hàng giá trị 120 thì 20 còn lại là m."},"249":{"idea":"Tăng cường độ thuần túy làm tăng cả lượng lao động và số sản phẩm tương ứng nên giá trị đơn vị không đổi.","example":"Làm gấp sức tạo 20 món, tổng giá trị 200 thay 10 món/100: vẫn 10 giá trị mỗi món, giả định năng suất không đổi."},"250":{"idea":"Cung phản ánh phía sản xuất, cầu phản ánh phía tiêu dùng có khả năng thanh toán; hai phía gặp nhau qua thị trường.","example":"Tiệm làm 100 ổ bánh là phía cung, khách đủ tiền muốn mua 80 ổ là phía cầu. Câu diễn đạt “thuộc khâu” cần hiểu mối liên hệ này."},"251":{"idea":"Tư bản là quan hệ kinh tế biểu hiện ở giá trị tự tăng thông qua lao động làm thuê, không đơn thuần là đồ vật.","example":"Một máy may dùng tự khâu áo gia đình là công cụ; được đưa vào quan hệ thuê lao động để thu m thì mang chức năng tư bản."},"252":{"idea":"Cố định/lưu động căn cứ phương thức chuyển giá trị: dần từng phần hay hết trong một chu kỳ.","example":"Xe giao hàng dùng nhiều năm phân bổ hao mòn dần; nhiên liệu dùng hết trong chuyến chuyển toàn bộ giá trị đã tiêu dùng."},"253":{"idea":"Tự cung tự cấp: làm để chính người sản xuất dùng; hàng hóa: làm để trao đổi.","example":"Gia đình nuôi gà chủ yếu lấy trứng ăn khác hộ nuôi gà theo đơn của cửa hàng. Xét mục đích chứ không chỉ quy mô."},"254":{"idea":"Lao động phức tạp cần đào tạo/huấn luyện chuyên môn. Có thể vừa dùng trí óc vừa dùng tay.","example":"Thợ sửa vi mạch phải học kỹ năng và thao tác chính xác; không thể coi mọi việc chân tay là giản đơn."},"255":{"idea":"Bài học lạm phát cao nhấn mất sức mua tiền; mua tài sản/hàng hóa giữ giá trị là đáp án trong giả định đề, không phải lời hứa sinh lợi.","example":"Cùng 100 nghìn mua được ít thực phẩm hơn khi giá tăng. Vàng hoặc hàng tồn kho vẫn có rủi ro giảm giá, hư hỏng và chi phí giữ."},"256":{"idea":"Tích lũy đủ tiền là điều kiện quy mô; dùng tiền nhằm thu giá trị thặng dư mới quyết định chức năng tư bản.","example":"Tiền cất trong két khác tiền ứng mua đầu vào và thuê thợ để sản xuất, bán hàng, thu T′ lớn hơn T."},"257":{"idea":"Nguồn mâu thuẫn câu 365: quy luật cơ bản của CNTB là giá trị thặng dư; quy luật giá trị là cơ bản của sản xuất hàng hóa.","example":"“Hàng hóa nói chung” hỏi trao đổi theo hao phí xã hội; “tư bản” hỏi mục đích tạo m. Hai phạm vi không được hoán đổi."},"258":{"idea":"Phát hiện của Mác là cùng một lao động sản xuất hàng hóa có hai mặt: cụ thể và trừu tượng.","example":"May áo vừa là thao tác nghề tạo áo để mặc, vừa hao phí lao động nói chung tạo giá trị. Không phải hai người hoặc hai ca làm riêng."},"259":{"idea":"Học thuyết giá trị thặng dư là hòn đá tảng vì giải thích nguồn gốc và quan hệ chiếm hữu phần giá trị tăng thêm.","example":"Chủ trả công đúng giá trị sức lao động vẫn thu m: câu hỏi “phần tăng thêm ở đâu?” là trung tâm, vượt cách nhìn chỉ mua rẻ bán đắt."},"260":{"idea":"Đề hỏi điều kiện sản xuất hàng hóa nhưng lựa chọn lại mô tả tăng năng suất. Không có đáp án khớp; đừng học khóa A như một điều kiện.","example":"Đúng phải là phân công + tách biệt kinh tế. Một gia đình trồng rau nhanh gấp đôi vẫn có thể hoàn toàn tự cung tự cấp."},"261":{"idea":"Lượng giá trị có thể thay đổi khi thời gian lao động xã hội cần thiết thay đổi; “luôn luôn” trong PDF không có nghĩa từng giây đều biến động.","example":"Công nghệ mới phổ biến làm một áo từ 2 giờ còn 1 giờ xã hội cần thiết, lượng giá trị áo giảm theo điều kiện mới."},"262":{"idea":"Lợi nhuận là hình thức biểu hiện của m; bản chất chung theo Mác là phần lao động thặng dư không được trả công.","example":"Sổ sách thấy doanh thu trừ chi phí; phân tích sâu tách giá trị cũ và giá trị mới để tìm phần người lao động tạo vượt giá trị sức lao động."},"263":{"idea":"Cả năng suất và cường độ tăng đều làm nhiều sản phẩm hơn trong cùng thời gian; nguyên nhân và tác động giá trị khác nhau.","example":"Máy tốt hơn hoặc người làm gấp sức đều có thể tăng từ 10 lên 20 món/giờ. Chỉ nhìn số món chưa xác định được cách nào."},"264":{"idea":"c/v chia theo vai trò trong tạo m: c bảo tồn/chuyển giá trị; v gắn lao động sống tạo v+m. Đừng dùng tiêu chí chuyển nhanh/chậm.","example":"Bột và lò đều thuộc c dù bột dùng hết còn lò dùng nhiều năm; tiền mua sức lao động là v."},"265":{"idea":"“Bất biến” nghĩa giá trị tư liệu sản xuất không tự tăng trong quá trình chuyển vào hàng, không có nghĩa máy không hao mòn.","example":"Máy hao mòn 10 đơn vị thì chuyển 10 vào sản phẩm; không từ 10 tự sinh thành 15 giá trị mới."},"266":{"idea":"Giá trị thặng dư là phần giá trị mới vượt giá trị sức lao động, do lao động thặng dư tạo ra và bị chiếm hữu.","example":"v=200, giá trị mới v+m=350 → m=150. Không lấy toàn bộ doanh thu 350 làm m nếu còn giá trị cũ trong hàng."},"267":{"idea":"Giá trị sử dụng trả lời “dùng để làm gì?”, khác giá trị trả lời về lao động xã hội kết tinh.","example":"Bún giúp ăn no; áo giúp mặc; dù đều bán được, công dụng của chúng không giống nhau."},"268":{"idea":"Nguồn giá trị là lao động trừu tượng trong sản xuất; lưu thông thuần túy chỉ thực hiện hoặc phân phối lại giá trị.","example":"Bàn được làm trong xưởng rồi bán ở cửa hàng; đổi chủ sở hữu không tự thêm lao động đã kết tinh trong bàn."},"269":{"idea":"Phương án A tự mâu thuẫn “do con người đặt ra” với “khách quan”, nên khóa “tất cả” cần đối chiếu. Quy luật khác luật pháp/chính sách.","example":"Nhà nước đặt thuế là chính sách; quan hệ cung cầu không do một người tùy ý ban hành. Đừng học chung hai loại “luật”."},"270":{"idea":"Thực thể giá trị là lao động trừu tượng: hao phí sức lao động nói chung đã kết tinh trong hàng.","example":"Khi so áo với gạo, gạt khác biệt động tác may/cấy để xét phần lao động xã hội chung, chứ không so công dụng mặc với ăn."},"271":{"idea":"Hao mòn hữu hình là giảm chất lượng vật chất do dùng hoặc tự nhiên. Nhớ “hữu hình = mòn thật”.","example":"Lưỡi cưa cùn, thân máy gỉ là hữu hình; máy còn tốt nhưng bị công nghệ mới làm mất giá thuộc vô hình."},"272":{"idea":"Lực lượng sản xuất có người lao động và tư liệu sản xuất; khoa học công nghệ thâm nhập, nâng sức sản xuất.","example":"Máy hiện đại cần người biết vận hành và quy trình khoa học; mua máy mà thiếu kỹ năng chưa tạo được năng lực như kỳ vọng."},"273":{"idea":"Câu nguồn giải thích vai trò cầm quyền theo tiến trình lịch sử khách quan của Việt Nam; không phải lựa chọn ngẫu nhiên một thời điểm.","example":"Gắn với chuỗi sự kiện lịch sử cách mạng và tổ chức lực lượng, thay vì học như một điều khoản về giá cả hay thị trường."},"274":{"idea":"Dù câu bị thiếu chữ, ý đang hỏi quan hệ lợi ích: lợi ích được xử lý hợp lý tạo động lực hoạt động.","example":"Thưởng gắn chất lượng giúp người lao động và chủ xưởng cùng có lợi; thưởng chỉ theo số lượng có thể làm tăng hàng lỗi."},"275":{"idea":"Quy luật giá trị yêu cầu sản xuất và trao đổi dựa vào hao phí lao động xã hội cần thiết. Nhớ “chuẩn xã hội”.","example":"Xưởng mất 3 giờ làm món mà xã hội thường chỉ cần 1 giờ không thể mặc nhiên bán giá gấp ba để bù sự chậm chạp."},"276":{"idea":"Tư liệu lao động gồm công cụ trực tiếp, vật chứa/bảo quản và hạ tầng sản xuất.","example":"Xưởng bánh có máy trộn, khay chứa và nhà xưởng: cả ba phục vụ lao động, còn bột là đối tượng lao động."},"277":{"idea":"Câu dùng mô hình tiền hàng hóa/tiền vàng trong lý luận cổ điển. Không áp nguyên xi rằng mọi thanh toán quốc tế hiện nay phải dùng vàng.","example":"Vàng làm chuẩn đo giá trị có thể tồn tại trong ý niệm; cất trữ vàng thì phải có vàng thật. Phân biệt vai trò chuẩn đo với hiện diện vật chất."},"278":{"idea":"Hai ý đi cùng nhau: xây nền vật chất của CNXH, nâng đời sống và thực hiện mục tiêu dân giàu–nước mạnh–dân chủ–công bằng–văn minh.","example":"Nhà máy nâng năng suất phải gắn việc làm, đời sống và tiến bộ xã hội; chỉ tăng sản lượng chưa bao quát đủ mục tiêu."},"279":{"idea":"Chọn cả mục tiêu năm giá trị và yêu cầu phân bổ nguồn lực hợp lý, tiết kiệm. Câu này có hai đáp án, không chỉ câu khẩu hiệu.","example":"Xây hạ tầng phục vụ người dân nhưng tránh dự án lãng phí: mục tiêu xã hội và sử dụng nguồn lực phải đi cùng nhau."},"280":{"idea":"Phân công lao động xã hội là chuyên môn hóa thành ngành, nghề khác nhau.","example":"Người làm nông, người chế biến, người vận tải chuyên việc riêng rồi trao đổi; khác phân việc cắt/khâu trong cùng một xưởng."},"281":{"idea":"Tái sản xuất giản đơn lặp cùng quy mô; mở rộng lặp với quy mô lớn hơn.","example":"Xưởng thay máy cũ để giữ 100 áo/ngày là duy trì; mua thêm máy để đạt 150 áo/ngày là mở rộng."},"282":{"idea":"Giá trị sử dụng của HÀNG HÓA phải hữu ích cho người khác, nên có ý nghĩa xã hội. Nhưng thuộc tính tự nhiên tạo công dụng không đồng nhất với bản chất xã hội của giá trị.","example":"Áo may để bán phải có người khác cần mặc; chỉ người may thích mà không ai dùng thì khó trở thành hàng hóa được chấp nhận."},"283":{"idea":"Sản xuất tư bản chủ nghĩa thống nhất làm giá trị sử dụng với tạo giá trị thặng dư; câu nhấn mục đích m.","example":"Xưởng làm giày phải tạo đôi giày dùng được để bán, nhưng chủ ứng vốn nhằm nhận phần giá trị tăng thêm."},"284":{"idea":"“Bình thường” trong nguồn nên hiểu lạm phát là hiện tượng có thể gặp trong kinh tế tiền tệ, không phải luôn có ích hoặc vô hại.","example":"Giá tăng chậm và giá tăng phi mã có tác động rất khác. Không dùng một từ trong đáp án để kết luận mọi mức lạm phát đều tốt."},"285":{"idea":"Cái chung để so các hàng hóa khác công dụng là lao động xã hội kết tinh trong chúng.","example":"Gạo để ăn, vải để mặc; vẫn đổi được theo tỷ lệ vì xét nền tảng giá trị chung, không cần công dụng giống nhau."},"286":{"idea":"Khóa PDF sai dấu hiệu rõ: k=c+v là chi phí sản xuất; c+v+m là giá trị hàng hóa. Không có lựa chọn đúng chuẩn trong câu này.","example":"c=80, v=20, m=20: k=100, giá trị=120. Thêm m vào k sẽ xóa mất phần chênh cần giải thích.","source":{"title":"Giáo trình Bộ GD&ĐT · chi phí sản xuất tư bản chủ nghĩa","url":"https://kmacle.duytan.edu.vn/uploads/2eae0e86-e7c6-431d-aa08-b8f89ba71921_giaotrinhkinhtechinhtri.pdf"}},"287":{"idea":"Bản chất tích lũy: tư bản hóa giá trị thặng dư, biến phần dư thành vốn mới.","example":"Lợi nhuận được dùng mua thêm máy và thuê người để mở rộng là hình ảnh tái đầu tư; đem toàn bộ tiêu dùng cá nhân thì không phải tích lũy tư bản."},"288":{"idea":"Đề nói “hai mặt” nhưng chưa nêu rõ đối tượng. Nếu hỏi lao động: cụ thể/trừu tượng; nếu hỏi hàng hóa: giá trị sử dụng/giá trị.","example":"Chiếc áo dùng để mặc và có giá trị; công việc may có thao tác cụ thể và hao phí lao động chung. Nhớ đúng cặp theo chủ ngữ."},"289":{"idea":"Sản xuất hàng hóa phục vụ nhu cầu thị trường thông qua mua bán, không chỉ nhu cầu của chính người làm.","example":"Tiệm bánh khảo sát khách thích loại gì rồi làm để bán; nướng riêng cho bữa sáng gia đình là mục đích khác."},"290":{"idea":"Hai điều kiện nền: tư liệu sản xuất/tiền tập trung và lực lượng người lao động phải bán sức lao động.","example":"Có xưởng, máy trong tay chủ; có người tự do nhưng thiếu tư liệu để tự sản xuất: hai phía gặp nhau trong quan hệ làm thuê."},"291":{"idea":"Xét chu chuyển dùng cố định/lưu động, vì cần biết vốn quay về từng phần hay toàn bộ qua mỗi chu kỳ.","example":"Tiền đầu tư lò quay về dần qua nhiều mẻ bánh; tiền bột quay về khi bán mẻ đó, ảnh hưởng tốc độ vòng vốn."},"292":{"idea":"Mác phát hiện tính hai mặt của lao động sản xuất hàng hóa: cụ thể và trừu tượng.","example":"Một người may, một quá trình làm áo, nhưng xét công dụng và tạo giá trị là hai góc nhìn; không phải hai loại lao động tách rời."},"293":{"idea":"Theo lý luận Mác, khủng hoảng nảy sinh từ mâu thuẫn khách quan của sản xuất tư bản, không chỉ do một cá nhân quản lý kém.","example":"Nhiều hãng cùng mở rộng vì lợi nhuận nhưng sức mua không theo kịp có thể gây hàng tồn và đổ vỡ diện rộng."},"294":{"idea":"Phân công lao động là điều kiện sản xuất hàng hóa, không đảo thành sản xuất hàng hóa là nguồn gốc duy nhất của phân công.","example":"Trong gia đình tự cung tự cấp vẫn có người trồng trọt, người chăn nuôi; phân việc có thể tồn tại trước mua bán hàng hóa."},"295":{"idea":"Lượng giá trị đo bằng thời gian lao động xã hội cần thiết, không bằng thời gian riêng của người chậm nhất.","example":"Xã hội thường cần 1 giờ làm một món; người mới học mất 4 giờ không thể vì vậy đòi giá trị gấp bốn."},"296":{"idea":"Kinh tế tự nhiên/tự cung tự cấp có trước kinh tế hàng hóa. Sự chuyên môn hóa và tách biệt làm trao đổi phát triển.","example":"Gia đình làm gần mọi thứ để tự dùng, rồi dần chuyên một nghề và đổi lấy thứ khác: hình dung bước chuyển mục đích sản xuất."},"297":{"idea":"T′>T đặt câu hỏi: phần tăng thêm từ đâu khi trao đổi ngang giá không tự tạo giá trị mới? Bất đẳng thức chỉ là dấu hiệu của mâu thuẫn.","example":"Đổi 100 lấy hàng đúng giá 100 rồi đổi lại ngang giá vẫn 100; cần xét hàng hóa đặc biệt sức lao động và quá trình sản xuất để giải thích m."},"298":{"idea":"M=m′×V, đổi tỷ lệ phần trăm thành số nhân trước.","example":"V=40 triệu, m′=150% → M=1,5×40=60 triệu. M viết hoa hỏi tổng lượng, không phải tỷ lệ."},"299":{"idea":"Theo PDF của môn: kinh tế tư nhân là một động lực quan trọng; kinh tế nhà nước giữ vai trò chủ đạo. Bám cách diễn đạt tài liệu đang thi.","example":"Các cơ sở kinh doanh tư nhân tạo việc làm, cạnh tranh và đổi mới; đừng lấy vai trò “chủ đạo” của thành phần khác để trả lời."},"300":{"idea":"Chi phí tư bản c+v nhỏ hơn chi phí lao động xã hội c+v+m khi m>0. Khác nhau ở phần lao động thặng dư.","example":"Ứng 80 tư liệu + 20 sức lao động nhưng hàng chứa 120 giá trị: chủ trả 100, xã hội đã hao phí lượng lao động biểu hiện thành 120."},"301":{"idea":"Hai điều kiện sức lao động thành hàng hóa: tự do thân thể và thiếu tư liệu sản xuất cần để tự sống.","example":"Người có quyền chọn nơi làm nhưng không có xưởng/ruộng đủ nuôi mình phải bán sức lao động; thiếu một vế thì quan hệ điển hình khác đi."},"302":{"idea":"Cung là lượng hàng/dịch vụ người bán sẵn sàng và có khả năng đưa ra ở mức giá, thời gian nhất định; không phải mọi thứ tồn tại trong kho.","example":"Tiệm có thể làm 100 ổ bánh/ngày và muốn bán ở giá đã định: đó là lượng cung; bánh chỉ để nhà ăn không tự thuộc cung thị trường."},"303":{"idea":"Giá trị đơn vị phụ thuộc năng suất và mức độ phức tạp lao động. Năng suất tăng làm giảm; lao động phức tạp được quy thành nhiều lao động giản đơn.","example":"Cùng một giờ, nghề cần đào tạo có thể tạo lượng giá trị quy đổi lớn hơn; cùng loại lao động, máy tốt hơn lại chia giá trị trên nhiều sản phẩm hơn."},"304":{"idea":"Tích tụ và tập trung đều làm tư bản cá biệt lớn hơn; chỉ tích tụ trực tiếp tăng tư bản xã hội qua m được tư bản hóa.","example":"Xưởng dùng lãi mua máy là tích tụ; hai xưởng gộp vốn là tập trung. Xưởng lớn lên ở cả hai, tổng vốn xã hội không nhất thiết tăng ở trường hợp gộp."},"305":{"idea":"Siêu ngạch là biến tướng tương đối: đều dựa tăng năng suất, nhưng siêu ngạch trước hết là ưu thế cá biệt.","example":"Xưởng A làm áo 1 giờ khi mức xã hội là 2 giờ, bán theo mặt bằng chung nên có phần vượt thêm; khi mọi xưởng cùng cải tiến, lợi thế riêng mất."},"306":{"idea":"Trong sơ đồ lịch sử, phương thức tư bản chủ nghĩa thay thế phong kiến.","example":"Hình dung chuyển từ địa chủ–nông dân lệ thuộc sang chủ tư bản–lao động làm thuê; không chỉ là thay người cai quản."},"307":{"idea":"Cả tô tuyệt đối và chênh lệch đều lấy từ giá trị thặng dư do lao động nông nghiệp tạo ra; khác điều kiện hình thành.","example":"Công nhân làm ra giá trị mới, nhà tư bản nông nghiệp giữ lợi nhuận bình quân và nộp phần tô cho chủ đất; đất không tự sinh giá trị mới."},"308":{"idea":"Cartel vẫn độc lập cả sản xuất và lưu thông, chỉ thỏa thuận một số điều kiện. Mất độc lập lưu thông là Syndicate.","example":"Các hãng tự làm và tự bán nhưng hẹn giá là Cartel; gom về một đầu mối bán chung gợi Syndicate. Câu chọn sai cố đổi hai tên."},"309":{"idea":"OECD viết tắt Organisation for Economic Co-operation and Development: Hợp tác và Phát triển Kinh tế.","example":"Chữ E gợi Economic, D gợi Development; đừng lẫn WTO thiên về thương mại với OECD về hợp tác/phát triển kinh tế."},"310":{"idea":"Tư bản tài chính tập trung quyền lực kinh tế vào các nhóm tài phiệt; “tài” gắn kiểm soát ngân hàng và công nghiệp.","example":"Một nhóm kiểm soát nhiều doanh nghiệp qua vốn và tín dụng có ảnh hưởng rộng hơn chủ một xưởng riêng."},"311":{"idea":"Conglomerate trong đề nhấn kinh doanh đa ngành và thao tác vốn/chứng khoán để tìm lợi nhuận. Không hiểu mọi tập đoàn đa ngành chỉ kiếm tiền từ chứng khoán.","example":"Công ty mẹ mua, bán cổ phần nhiều ngành không cùng chuỗi sản xuất; điểm gợi nhớ là danh mục vốn đa dạng."},"312":{"idea":"Cấu tạo giá trị nhìn tỷ lệ c/v trong tổng vốn, cho thấy vốn phân bổ cho tư liệu sản xuất và sức lao động.","example":"100 vốn gồm 80 c và 20 v có cấu tạo giá trị 4/1; đếm số máy/người lại là góc cấu tạo kỹ thuật."},"313":{"idea":"m′=(m/v)×100%: phần thặng dư so với vốn mua sức lao động. Chỉ v ở mẫu số.","example":"m=60, v=40 → m′=150%. Thêm c vào mẫu sẽ biến thành phép tính tỷ suất lợi nhuận, sai đại lượng đang hỏi."},"314":{"idea":"Vòng vốn nhanh làm tăng M và tỷ suất giá trị thặng dư HẰNG NĂM trên vốn ứng trước. Không tự tăng m′ của một vòng hay trình độ bóc lột.","example":"Ứng V=10, mỗi vòng m′=100%: quay 2 vòng thu M=20; quay 4 vòng thu M=40. m′ mỗi vòng vẫn 100%; đề thiếu chữ “hằng năm”."},"315":{"idea":"Chức năng thực tiễn là dùng hiểu biết quy luật để điều chỉnh hành vi/chính sách nhằm có kết quả tốt hơn.","example":"Thấy hàng tồn, doanh nghiệp đổi kế hoạch sản xuất theo nhu cầu: kiến thức được chuyển thành hành động thực tế."},"316":{"idea":"Cố định và lưu động đều là bộ phận của tư bản sản xuất, phân theo cách thu hồi/chuyển giá trị.","example":"Trong xưởng, máy là cố định; nguyên liệu và vốn sức lao động là lưu động. Tiền đang chờ đầu tư không tự được gọi máy cố định."},"317":{"idea":"Với c>0, m>0: p′=m/(c+v) thấp hơn m′=m/v do chia cùng tử cho mẫu lớn hơn.","example":"m=30, c=70, v=30: p′=30%, m′=100%. Nhìn mẫu số trước sẽ tránh học nhầm hai công thức."},"318":{"idea":"Trọng thương tập trung lưu thông, nhất là ngoại thương. “Thương” gợi buôn bán.","example":"Hình dung tàu chở hàng, thương nhân và vàng thu về, khác ruộng đất tạo sản phẩm ròng của trọng nông."},"319":{"idea":"Môn học nghiên cứu quan hệ người–người trong sản xuất, không chỉ kỹ thuật người–vật.","example":"Một dây chuyền: kỹ sư hỏi máy chạy thế nào; kinh tế chính trị hỏi ai sở hữu, ai làm, ai nhận phần thu nhập."},"320":{"idea":"Kinh tế hàng hóa tiếp nối kinh tế tự nhiên khi chuyên môn hóa và trao đổi phát triển.","example":"Từ tự trồng, tự dệt cho gia đình chuyển sang chuyên dệt vải rồi bán lấy tiền mua gạo: thay đổi mục đích và quan hệ kinh tế."},"321":{"idea":"Adam Smith ví tiền như bánh xe lưu thông: giúp trao đổi chuyển động thuận lợi, không đồng nhất tiền với toàn bộ của cải.","example":"Có tiền, người bán cá mua gạo không cần tìm người vừa có gạo vừa muốn cá; tiền giúp nối các giao dịch."},"322":{"idea":"Tô chênh lệch gắn độc quyền kinh doanh ruộng đất có điều kiện khác nhau; tô tuyệt đối gắn độc quyền tư hữu đất.","example":"Ruộng tốt tạo lợi thế so với ruộng xấu → chênh lệch; ngay ruộng xấu vẫn phải trả cho chủ đất → tuyệt đối."},"323":{"idea":"G=c+v+m: giá trị cũ chuyển vào + giá trị sức lao động + thặng dư. Nếu hỏi đơn vị, phải chia tổng các phần cho số sản phẩm.","example":"Lô 10 món có c=60, v=20, m=20 → tổng 100, mỗi món 10. Đừng dùng chi phí cả lô làm giá trị một món."},"324":{"idea":"Khủng hoảng 1873 là mốc thúc đẩy tập trung doanh nghiệp và độc quyền trong cách trình bày của đề.","example":"Khi nhiều hãng nhỏ phá sản, hãng lớn mua lại nhà xưởng và thị phần; hình dung khủng hoảng như cú tăng tốc quá trình tập trung đã có."},"325":{"idea":"Căn nguyên khủng hoảng gắn mâu thuẫn giữa sản xuất xã hội hóa và chiếm hữu tư nhân tư bản chủ nghĩa.","example":"Nhiều doanh nghiệp tự mở rộng để tìm lãi, nhưng toàn xã hội không bảo đảm sức mua tăng tương ứng; mất cân đối có thể tích tụ."},"326":{"idea":"Vàng cố định vai trò vật ngang giá chung → hình thái tiền tệ.","example":"Trước đó nhiều vật có thể làm trung gian; khi vàng được dùng thống nhất để biểu hiện giá các hàng, trao đổi có một chuẩn chung."},"327":{"idea":"Khóa A mâu thuẫn lý thuyết: lượng m ảnh hưởng trực tiếp quy mô tích lũy khi tỷ lệ dành tích lũy không đổi. Không nên học câu phủ định này.","example":"Cùng tích lũy 50%, m=100 cho 50 vốn mới; m=200 cho 100. Con số chứng minh lượng m có ảnh hưởng."},"328":{"idea":"Quy luật kinh tế tác động qua lợi ích, từ đó điều chỉnh hành vi con người.","example":"Giá một mặt hàng tăng làm người bán muốn tăng sản lượng và người mua cân nhắc mua ít lại: động cơ lợi ích truyền tác động."},"329":{"idea":"Ba giai đoạn: mua đầu vào → sản xuất → bán hàng; tương ứng tiền tệ–sản xuất–hàng hóa.","example":"Tiền mua bột, thợ làm bánh, bánh bán lấy tiền. Bỏ khâu sản xuất sẽ không giải thích được nguồn giá trị mới."},"330":{"idea":"Điền “tự do cạnh tranh”: cạnh tranh làm tập trung, tập trung đến mức cao dẫn tới độc quyền.","example":"Các hãng đua giảm chi phí, hãng yếu bị mua lại, vài hãng lớn còn lại chi phối ngành; nhớ chiều mũi tên thay vì đảo nguyên nhân."},"331":{"idea":"Công bằng theo mức độ xét mức thu nhập nhận được; theo chức năng xét đóng góp tạo ra thu nhập. Nhớ “nhận bao nhiêu / góp bao nhiêu”.","example":"Hai người cùng nhận 10 triệu là nhìn mức nhận; xem ai đóng góp gì để đánh giá cách chia là nhìn chức năng. Không đồng nhất công bằng với chia đều.","source":{"title":"Giáo trình KTCT · công bằng trong phân phối","url":"https://hcmunre.edu.vn/upload/elfinder/Trang%20Khoa/Khoa%20Luat%20%26LLCT/Ph%E1%BA%A7n%202_GT%20h%E1%BB%8Dc%20ph%E1%BA%A7n%20Kinh%20t%E1%BA%BF%20ch%C3%ADnh%20tr%E1%BB%8B%20MNL%20%28K%29%20Tr101-%20Tr182.pdf"}},"332":{"idea":"Lượng tiền cần thiết tỷ lệ thuận tổng giá cả, nghịch tốc độ lưu thông. Một đồng quay nhiều vòng thì cần ít đồng hơn.","example":"Tổng giao dịch 1.000, mỗi đồng quay 5 vòng → cần 200; quay 10 vòng → cần 100, trong mô hình giản lược không xét tín dụng."},"333":{"idea":"Mua sức lao động đúng giá trị vẫn có m, vì dùng nó tạo lượng giá trị mới lớn hơn giá trị sức lao động.","example":"Giá trị sức lao động 300, lao động ngày tạo 500 giá trị mới → m=200 dù tiền công trả đủ 300."},"334":{"idea":"Mức hao phí của nhóm sản xuất cung ứng đại bộ phận hàng thường đại diện điều kiện xã hội bình thường.","example":"Nếu phần lớn áo được làm bằng máy trong 1 giờ, vài thợ mất 3 giờ không quyết định chuẩn xã hội là 3 giờ."},"335":{"idea":"Trình độ lực lượng sản xuất là cơ sở quy định quan hệ sở hữu và hình thức tổ chức tương ứng; quan hệ này có tác động qua lại.","example":"Một công cụ nhỏ có thể do hộ tự dùng; hệ thống công nghiệp liên kết quy mô lớn đòi cách huy động và tổ chức sở hữu phức tạp hơn."},"336":{"idea":"Hàng hóa cần ba ý: sản phẩm lao động, có ích, đi qua trao đổi/mua bán.","example":"Không khí tự nhiên có ích nhưng không do lao động sản xuất; bánh làm riêng để ăn có lao động nhưng chưa nhằm trao đổi. Bánh để bán hội đủ."},"337":{"idea":"M viết hoa phản ánh quy mô giá trị thặng dư bằng lượng tiền; m′ phản ánh mức độ bằng tỷ lệ.","example":"Xưởng A thu 100 triệu, B thu 200 triệu: B có M lớn hơn, nhưng chưa kết luận m′ cao hơn nếu chưa biết V."},"338":{"idea":"Giá trị sử dụng hàng hóa hướng tới người mua/người khác, không chỉ người làm ra thích nó.","example":"Bạn may áo để bán: kích cỡ và kiểu phải đáp ứng khách; bản thân bạn thấy đẹp chưa đủ bảo đảm có người mua."},"339":{"idea":"Trọng nông chuyển trọng tâm từ lưu thông sang sản xuất, nhưng chủ yếu nông nghiệp. Nhớ “nông–ruộng–sản phẩm ròng”.","example":"Nhìn một mùa gieo hạt rồi thu hoạch nhiều hơn đầu vào là hình ảnh họ dùng để nghĩ về nguồn của cải; không phải kết luận hiện đại chỉ nông nghiệp tạo giá trị."},"340":{"idea":"Nhà nước điều tiết để hỗ trợ ổn định, xử lý khuyết tật và định hướng; cơ chế thị trường vẫn có vai trò phân bổ.","example":"Thị trường quyết nhiều giá mua bán, nhà nước đặt chuẩn an toàn và xử lý ô nhiễm; điều tiết không đồng nghĩa quyết thay mọi đơn hàng."},"341":{"idea":"Liên kết ngang cùng ngành; liên kết dọc khác khâu liên quan trong chuỗi sản xuất.","example":"Hai hãng thép gộp là ngang; mỏ quặng–luyện thép–phân phối gắn nhau là dọc. Vẽ ngang/dọc theo chuỗi giúp nhớ."},"342":{"idea":"p′=p/(c+v)×100%: lợi nhuận so với toàn bộ vốn ứng trước. Phân biệt m′ chỉ chia v.","example":"Lãi 20 trên vốn 100 → p′=20%; nếu v chỉ 20 thì m′ tương ứng có thể 100% trong ví dụ p=m."},"343":{"idea":"Cạnh tranh thúc đẩy tích tụ, tập trung rồi hình thành độc quyền. Hai hiện tượng liên hệ chứ không loại trừ tuyệt đối.","example":"Doanh nghiệp mạnh thâu tóm đối thủ sau cuộc đua giá, tạo vị thế lớn hơn; khi đã lớn vẫn có thể cạnh tranh với tập đoàn khác."},"344":{"idea":"Xuất khẩu vốn nhà nước về kinh tế có thể xây điều kiện thuận lợi cho vốn tư nhân, nhất là hạ tầng vốn lớn/chậm thu hồi.","example":"Vốn công hỗ trợ cảng, đường, điện ở nơi nhận đầu tư; sau đó doanh nghiệp tư nhân có điều kiện đặt nhà máy và vận chuyển hàng."},"345":{"idea":"Bàn tay vô hình = cơ chế giá và cạnh tranh phối hợp các quyết định riêng lẻ, theo Adam Smith.","example":"Giá bún tăng hút thêm quán mở bán; cạnh tranh khiến quán cải thiện và điều chỉnh giá, dù không ai lập kế hoạch cho mọi quán."},"346":{"idea":"Công ty xuyên quốc gia tổ chức sản xuất, vốn và tiêu thụ trên nhiều nước, thúc đẩy quốc tế hóa.","example":"Một điện thoại dùng thiết kế, linh kiện, lắp ráp và phân phối từ nhiều nước: chuỗi doanh nghiệp nối các nền kinh tế."},"347":{"idea":"Giản đơn/phức tạp là các mức trình độ lao động; cụ thể/trừu tượng là hai mặt của cùng lao động. Đừng đổi hai cặp.","example":"Quét dọn thông thường và sửa máy chuyên sâu khác mức đào tạo; công việc sửa máy vẫn đồng thời có mặt cụ thể và trừu tượng."},"348":{"idea":"Các nét mới trong đề: vốn luân chuyển giữa nước phát triển, vai trò TNC, hình thức đa dạng, nguyên tắc cùng có lợi. Nguyên tắc không bảo đảm mọi dự án đều công bằng.","example":"Một tập đoàn đầu tư nhà máy, mua cổ phần hoặc cho vay ở nước khác: đường đi và hình thức vốn phong phú hơn sơ đồ một chiều."},"349":{"idea":"Dịch vụ là hàng hóa vô hình: lợi ích thường nằm ở hoạt động được cung cấp, không phải vật cầm nắm.","example":"Trả tiền cắt tóc là mua hoạt động phục vụ; chai dầu gội là hàng hữu hình. Dịch vụ vẫn có thể dùng công cụ vật chất."},"350":{"idea":"Đối tượng lao động là thứ được tác động, biến đổi; tư liệu lao động là thứ dùng để tác động.","example":"Thợ mộc dùng cưa cắt gỗ: gỗ là đối tượng, cưa là tư liệu; người thợ là chủ thể lao động."},"351":{"idea":"Lợi nhuận là hình thức biến tướng của m, khi phần dư được nhìn như kết quả toàn bộ vốn ứng ra.","example":"Doanh thu 120 trừ chi phí 100 thấy lãi 20; phân tích nguồn gốc 20 cần xét lao động tạo giá trị mới, không chỉ phép trừ kế toán."},"352":{"idea":"Lao động trừu tượng tạo giá trị; lao động cụ thể tạo công dụng. Nhớ “trừu–trị”.","example":"May áo tạo công dụng mặc qua nghề may; hao phí sức lao động nói chung là phần xét khi so giá trị áo với hàng khác."},"353":{"idea":"k=c+v, không cộng m. Đó là phần bù lại tư liệu sản xuất tiêu dùng và sức lao động đã mua.","example":"80 giá trị cũ + 20 tiền sức lao động = 100 chi phí; cộng 20 m mới thành 120 giá trị hàng hóa."},"354":{"idea":"Hữu hình là có dạng vật chất có thể cầm, lưu kho; mì, khăn giấy, đồ ăn đóng gói thuộc nhóm này.","example":"Gói mì trong siêu thị là hàng hữu hình; dịch vụ nấu/phục vụ bữa ăn có phần hoạt động vô hình."},"355":{"idea":"Sức lao động thành hàng hóa là điều kiện then chốt giải thích tiền thành tư bản trong sản xuất tư bản chủ nghĩa.","example":"Chủ dùng tiền mua sức lao động cùng đầu vào; chính lao động tạo v+m. Có tiền mà không đưa vào vận động tăng giá trị thì chưa đủ."},"356":{"idea":"Lần 1 gắn năng lượng hơi nước, giúp chuyển lao động thủ công sang cơ khí.","example":"Máy hơi nước truyền động cho máy dệt là hình ảnh nhớ; bóng đèn và động cơ điện gợi lần 2."},"357":{"idea":"Hai phương pháp: tuyệt đối kéo dài ngày; tương đối giảm thời gian tất yếu trong ngày không đổi.","example":"Từ 4+4 giờ sang 4+6 là tuyệt đối; sang 3+5 là tương đối. Cả hai tăng phần thặng dư so với tất yếu."},"358":{"idea":"Tăng trưởng là tăng quy mô sản lượng/thu nhập thực trong thời kỳ; khi dùng GDP/GNP cần loại ảnh hưởng tăng giá.","example":"Doanh thu toàn nền kinh tế tăng 10% nhưng giá tăng 10% chưa chứng minh sản lượng thực tăng 10%."},"359":{"idea":"Lần 4: kết nối số, dữ liệu lớn, AI và các công nghệ thông minh giao thoa.","example":"Máy in 3D tạo mẫu từ thiết kế số, cảm biến gửi dữ liệu, AI tối ưu vận hành: hình dung một hệ thống kết nối thay vì máy tính riêng lẻ."},"360":{"idea":"Định hướng thể hiện ở mục tiêu xã hội, sở hữu, quản lý, phân phối và huy động nguồn lực toàn dân; không chỉ một chính sách riêng.","example":"Phát triển doanh nghiệp đi cùng việc làm, an sinh và quản lý nhà nước: nhìn nhiều khía cạnh cùng hướng tới mục tiêu xã hội."},"361":{"idea":"Đưa giá trị ra nước ngoài để đầu tư thu m/nguồn lợi là xuất khẩu tư bản. Dấu nhận diện là vốn tạo quyền hưởng lợi.","example":"Cho doanh nghiệp nước ngoài vay vốn hoặc mở nhà máy ở đó là đầu tư; bán một lô gạo cho khách nước ngoài là xuất hàng hóa."},"362":{"idea":"Mục tiêu cao nhất là tìm quy luật chi phối quan hệ sản xuất và trao đổi, không chỉ mô tả hiện tượng riêng lẻ.","example":"Quan sát nhiều lần giá biến động để tìm quan hệ cung cầu sâu hơn việc ghi “hôm nay bún giá 40 nghìn”."},"363":{"idea":"Trust: sản xuất, tiêu thụ, tài vụ chung một ban quản trị. Nhớ “ba khâu cùng chung”.","example":"Các xưởng gộp quyền quản lý cả làm hàng, bán hàng và tiền vốn; mức liên kết sâu hơn chỉ lập đầu mối bán chung."},"364":{"idea":"Chênh lệch tỷ suất lợi nhuận hút vốn chuyển ngành; vốn chạy theo tỷ lệ sinh lời, không chỉ tổng tiền lãi.","example":"Lãi 10 trên vốn 100 là 10%; lãi 50 trên vốn 1.000 chỉ 5%. Ngành lãi tổng lớn chưa chắc hút vốn hơn theo tỷ suất."},"365":{"idea":"Sản xuất m là quy luật kinh tế cơ bản/tuyệt đối của CNTB: phản ánh mục đích và phương tiện đặc trưng.","example":"Doanh nghiệp ứng vốn để quay về có phần tăng thêm; khác quy luật giá trị điều chỉnh sản xuất và trao đổi hàng hóa nói chung."},"366":{"idea":"Trong lý luận tích lũy, c/v tăng làm nhu cầu lao động giảm tương đối so với tổng vốn, tạo nhân khẩu thừa tương đối.","example":"Vốn tăng gấp đôi nhưng máy tăng nhiều, số người chỉ tăng ít: không nhất thiết mọi nơi đều giảm người tuyệt đối, mà tỷ trọng lao động giảm."},"367":{"idea":"Bốn nhân tố p′: m′, chu chuyển, c/v, tiết kiệm c. Nhớ “Bóc lột–Vòng vốn–Cấu tạo–Tiết kiệm”.","example":"Cùng lãi mỗi vòng, bán nhanh hơn trong năm hoặc giảm lãng phí nguyên liệu có thể nâng lợi nhuận trên vốn ứng trước."},"368":{"idea":"Tư bản cố định như máy móc là điều kiện vật chất nâng năng suất; theo Mác không tự tạo giá trị mới.","example":"Máy cắt chính xác giúp thợ làm nhiều sản phẩm hơn mỗi giờ, nhưng giá trị máy chỉ chuyển dần qua hao mòn."},"369":{"idea":"Khóa “tư bản” phù hợp ý thị trường phát triển cao/phổ biến, nhưng chữ “xuất hiện lần đầu” mâu thuẫn câu 11 và 56. Cần đối chiếu câu gốc.","example":"Tách ba nhãn “mầm mống–hình thành–phát triển cao”; không dùng một năm/chế độ cho mọi cách hỏi."},"370":{"idea":"Quy luật khách quan nhưng phát huy tác dụng thông qua hoạt động con người; hai ý không mâu thuẫn.","example":"Không ai ban hành quy luật cung cầu, nhưng việc người mua giảm mua và người bán tăng cung làm quy luật biểu hiện."},"371":{"idea":"Lạm phát là mức giá chung tăng, không nhất thiết giá mọi mặt hàng đều tăng cùng lúc.","example":"Giá thực phẩm, nhà ở tăng đủ làm chỉ số chung tăng dù một mẫu điện thoại giảm giá; phải phân biệt mặt bằng với từng món."},"372":{"idea":"Đại hội IX (2001) chính thức nêu mô hình kinh tế thị trường định hướng XHCN. VI (1986) là mốc khởi xướng Đổi mới.","example":"Lập cặp nhắc: “VI–Đổi mới; IX–mô hình”. Câu hỏi đổi từ khóa thì đáp án mốc cũng có thể đổi."},"373":{"idea":"Chiến lược 2021–2030 nhấn tự chủ trên nền làm chủ công nghệ, hội nhập chủ động, đa dạng thị trường và thích ứng.","example":"Nhà sản xuất vừa tự làm được công nghệ cốt lõi, vừa bán ở nhiều thị trường để không phụ thuộc một khách hàng lớn."},"374":{"idea":"Tiền công biểu hiện bằng tiền của giá trị/giá cả sức lao động, bề ngoài dễ bị hiểu là trả cho toàn bộ lao động.","example":"Hợp đồng trả một ngày công; phân tích lý luận vẫn chia ngày thành tất yếu và thặng dư, không coi toàn bộ giá trị mới đều được trả lại."},"375":{"idea":"p và m chung nguồn gốc lao động thặng dư; khác hình thức nhìn và có thể khác lượng ở từng doanh nghiệp.","example":"Một bên nhìn phần lao động không được trả, bên kia nhìn doanh thu vượt chi phí; giao dịch và phân phối có thể làm p cá biệt lệch m."},"376":{"idea":"Tuần hoàn xét hình thái qua một vòng; chu chuyển xét tính lặp lại, thời gian và số vòng.","example":"Một mẻ bánh từ tiền đến tiền là tuần hoàn; mỗi tuần quay ba mẻ và năm quay bao nhiêu vòng là góc chu chuyển."},"377":{"idea":"Sức lao động đặc biệt vì sử dụng nó có thể tạo giá trị mới lớn hơn giá trị bản thân, nguồn giải thích m.","example":"Mua sức lao động giá trị 200, dùng trong sản xuất tạo 350 giá trị mới → chênh 150. Bột và máy không tự có tính chất này."},"378":{"idea":"Khóa nói sản xuất hàng hóa ra đời trong nô lệ; cần phân biệt với mầm mống trao đổi cuối cộng xã nguyên thủy. Các phương án còn lại cũng diễn đạt tuyệt đối.","example":"Trao đổi có thể xuất hiện khi phân công và tách biệt phát triển, trước khi một phương thức xã hội hoàn toàn định hình; không học mốc cứng khi đề thiếu phạm vi."},"379":{"idea":"Theo khung bài, thực dân mới dùng lệ thuộc kinh tế/quân sự thay cai trị thuộc địa trực tiếp. Không phải mọi viện trợ đều mặc nhiên là thực dân mới.","example":"Một khoản viện trợ kèm điều kiện chi phối chính sách có thể tạo lệ thuộc; cần xét điều kiện và quyền tự quyết, không chỉ tên “viện trợ”."},"380":{"idea":"Rút ngắn CNH cần giáo dục, đào tạo và khoa học công nghệ để tiếp thu rồi làm chủ thành tựu đi trước.","example":"Mua dây chuyền tiên tiến chỉ hiệu quả khi có kỹ sư vận hành, bảo trì, cải tiến; học nhanh giúp bỏ bớt bước thử sai."},"381":{"idea":"Lênin khái quát năm đặc điểm: tập trung/độc quyền, tài chính, xuất vốn, chia thị trường, chia lãnh thổ.","example":"Theo hành trình vốn từ nhà máy lớn → ngân hàng → ra nước ngoài → tranh khách hàng → cạnh tranh giữa cường quốc để nhớ đủ năm."},"382":{"idea":"Lệ thuộc mới có thể tồn tại dù độc lập chính trị: bị chi phối về kinh tế và đối ngoại.","example":"Một nước có chính phủ riêng nhưng phụ thuộc nặng vào một nguồn vốn, viện trợ hoặc thị trường nên khó tự quyết chính sách."},"383":{"idea":"Sở hữu độc quyền nhà nước thể hiện kết hợp sở hữu nhà nước với độc quyền tư nhân; không phải tất cả chuyển thành một chủ duy nhất.","example":"Nhà nước và tập đoàn cùng nắm vốn, tài sản và lợi ích trong dự án quy mô lớn là hình ảnh minh họa liên kết sở hữu."},"384":{"idea":"Lao động trừu tượng bỏ qua nghề cụ thể, xét hao phí cơ bắp, thần kinh, trí óc nói chung trong sản xuất hàng hóa.","example":"Thợ may và thợ mộc thao tác khác nhau nhưng đều hao phí sức lao động; mặt chung ấy là cơ sở phân tích giá trị."},"385":{"idea":"Hai thuộc tính: giá trị sử dụng và giá trị. Nhớ “dùng được + có lao động xã hội kết tinh”.","example":"Chiếc áo có công dụng mặc và có giá trị; giá bán bằng tiền là hình thức biểu hiện, không phải thuộc tính thứ ba."},"386":{"idea":"Lao động phức tạp được quy thành bội số lao động giản đơn; tỷ trọng phức tạp tăng thì cùng thời gian có thể tạo giá trị nhiều hơn.","example":"Nếu 1 giờ phức tạp được xã hội quy bằng 3 giờ giản đơn, tăng phần việc phức tạp làm lượng lao động quy đổi tăng; hệ số 3 chỉ minh họa."},"387":{"idea":"Phân công và tách biệt kinh tế sâu hơn mở rộng trao đổi và sự phong phú hàng hóa; không phải công thức mọi nơi tăng đều theo thời gian.","example":"Người chuyên chế biến, vận tải, thiết kế tạo thêm sản phẩm/dịch vụ trao đổi, khác hộ tự làm gần mọi thứ."},"388":{"idea":"Chia c/v để thấy nguồn m: c chuyển giá trị cũ; lao động sống được mua bằng v tạo v+m.","example":"Cùng xưởng, vải/máy không tự sinh m; người thợ tạo giá trị mới. Chia cố định/lưu động lại nhằm giải thích chu chuyển."},"389":{"idea":"Cầu là nhu cầu có khả năng thanh toán, gắn giá và thời điểm; chỉ thích một món chưa thành cầu hiện thực.","example":"Bạn muốn xe đắt nhưng chưa đủ tiền: đó là mong muốn. Số người sẵn sàng, có khả năng mua ở giá đang xét tạo lượng cầu."},"390":{"idea":"Nguồn m nằm ở việc sử dụng sức lao động, không phải mua dưới giá hoặc tiền tự đẻ tiền.","example":"Trả đủ giá trị sức lao động 300 nhưng lao động tạo 500 giá trị mới: m=200 xuất hiện trong sản xuất."},"391":{"idea":"m′=m/v×100%; đồng thời bằng thời gian thặng dư/thời gian tất yếu ×100%.","example":"Ngày 8 giờ có 3 tất yếu, 5 thặng dư → m′=5/3×100%≈166,7%, không phải 5/8."},"392":{"idea":"Sức lao động là khả năng thể lực và trí lực; lao động là quá trình sử dụng khả năng đó.","example":"Người thợ đang nghỉ vẫn có sức lao động; khi cầm dụng cụ sửa xe, họ đang lao động. Khả năng khác hoạt động thực tế."},"393":{"idea":"Cố định tham gia toàn bộ về hiện vật nhưng giá trị chuyển từng phần qua nhiều chu kỳ.","example":"Lò bánh vẫn nguyên chiếc trong mỗi mẻ; mỗi mẻ chỉ gánh một phần hao mòn, không gánh toàn bộ giá mua lò."},"394":{"idea":"Cách mạng 3 dùng điện tử, CNTT, máy tính để tự động hóa. Dấu nhớ là máy chạy theo chương trình.","example":"Máy CNC làm theo mã điều khiển thay nhiều thao tác thủ công; lần 4 nhấn kết nối, dữ liệu và thông minh hơn toàn hệ thống."},"395":{"idea":"Lực lượng sản xuất và ngành mới phát triển khiến tài chính mở rộng cách liên kết, quản lý, kiểm soát vốn.","example":"Tập đoàn từ công nghiệp truyền thống mở sang công nghệ, dịch vụ và quỹ đầu tư; mô hình nắm vốn cũng phức tạp hơn."},"396":{"idea":"Tích tụ, tập trung sản xuất tạo xí nghiệp lớn; quy mô đủ cao là cơ sở hình thành tổ chức độc quyền.","example":"Một cơ sở lớn dần nhờ tái đầu tư rồi nhiều cơ sở hợp nhất, đủ sức tác động nguồn cung và giá ngành."},"397":{"idea":"Đầu tư danh mục qua cổ phiếu/trái phiếu thường là gián tiếp; mua cổ phần để kiểm soát quản lý có thể thuộc đầu tư trực tiếp tùy trường hợp.","example":"Mua ít cổ phiếu chỉ để hưởng cổ tức/tăng giá khác việc mua cổ phần chi phối và trực tiếp điều hành nhà máy."},"398":{"idea":"Giá trị là lao động trừu tượng kết tinh trong hàng hóa; công dụng chỉ nói hàng đáp ứng nhu cầu gì.","example":"Hai loại bàn khác kiểu dáng vẫn có thể so giá trị trên hao phí lao động xã hội, không chỉ đẹp hay xấu theo sở thích cá nhân."},"399":{"idea":"Đơn vị đo lượng giá trị là thời gian lao động xã hội cần thiết; tiền biểu hiện giá trị thành giá cả.","example":"Xã hội cần 2 giờ để làm một món trong điều kiện bình thường: đó là lượng thời gian chuẩn, không phải thời gian của người chậm nhất."},"400":{"idea":"Năng suất và giá trị một đơn vị đi ngược chiều khi điều kiện khác không đổi: năng suất ×k thì giá trị đơn vị ÷k.","example":"Cùng 8 giờ làm 8 bàn rồi 16 bàn, lao động tính cho mỗi bàn giảm một nửa. Tổng giá trị mới do cùng lượng lao động tạo ra không vì vậy tự gấp đôi."},"401":{"idea":"Tư bản cho vay là hàng hóa đặc biệt: bán quyền sử dụng tạm thời, không bán đứt quyền sở hữu; giá của quyền dùng là lợi tức.","example":"Cho vay 100, cuối kỳ nhận lại 100 cộng 5 lợi tức: người vay được dùng vốn, người cho vay vẫn có quyền đòi vốn."},"402":{"idea":"Trong giai đoạn độc quyền, quy luật m biểu hiện thành quy luật lợi nhuận độc quyền cao. Phân biệt giá cả độc quyền là biểu hiện của quy luật giá trị.","example":"Tập đoàn dùng ưu thế để mua thấp, bán cao nhằm thu lợi nhuận vượt mức bình thường; m vẫn không tự xuất hiện từ một con số giá."},"403":{"idea":"Hữu hình là máy mòn/gỉ thật; vô hình là mất giá do công nghệ hoặc chi phí tái sản xuất thay đổi.","example":"Máy cũ hỏng bánh răng: hữu hình. Máy vẫn chạy tốt nhưng mẫu mới rẻ, hiệu quả hơn làm máy cũ mất giá: vô hình."},"404":{"idea":"NICs viết tắt các nước công nghiệp mới; đề nói mô hình Nhật Bản và NICs. Nhật Bản không vì vậy được xếp là một NIC.","example":"Hình dung Nhật Bản là trường hợp công nghiệp hóa đi trước, các nền kinh tế như Singapore là nhóm mới; cùng được dùng so sánh mô hình rút ngắn."},"405":{"idea":"Bản chất là kết hợp sức mạnh độc quyền tư nhân với nhà nước tư sản thành cơ chế thống nhất phục vụ hệ thống.","example":"Một tập đoàn và nhà nước gắn nhân sự, vốn, chính sách: cần thấy cả hai bên, không chỉ doanh nghiệp nhà nước đơn lẻ."},"406":{"idea":"Theo lý luận Mác, quan hệ sản xuất phải phù hợp lực lượng sản xuất, nên CNTB có tính lịch sử chứ không vĩnh viễn.","example":"Cách tổ chức phù hợp xưởng nhỏ có thể trở thành hạn chế khi sản xuất liên kết toàn xã hội; đây là logic về biến đổi lịch sử, không dự báo ngày kết thúc cụ thể."},"407":{"idea":"Đề thiếu bối cảnh: đáp án nói độc quyền tư bản, nhưng ghi chú lại chuyển sang Việt Nam. Không dùng chung khóa cho hai hệ thống.","example":"Nếu hỏi Việt Nam theo giáo trình, mục tiêu là lợi ích nhân dân; nếu hỏi độc quyền nhà nước tư bản, phân tích lợi ích độc quyền. Chủ ngữ quyết định ý trả lời."},"408":{"idea":"Khoa học công nghệ phát hiện và tạo thêm công dụng, làm giá trị sử dụng phong phú hơn.","example":"Điện thoại từ gọi điện thêm bản đồ, chụp ảnh, học trực tuyến: nhiều nhu cầu được đáp ứng hơn, không có nghĩa giá trị lao động nhất thiết tăng cùng chiều."},"409":{"idea":"Cá biệt/xã hội chia theo phạm vi; giản đơn/mở rộng chia theo quy mô. Nhớ hai trục phân loại.","example":"Xem một xưởng bánh là cá biệt; xem toàn nền kinh tế gồm bột, điện, vận tải, bánh là xã hội. Cả hai phạm vi đều có thể giữ nguyên hoặc mở rộng."},"410":{"idea":"Chiều sâu tăng sản lượng chủ yếu nhờ năng suất, công nghệ và hiệu quả; chiều rộng chủ yếu thêm đầu vào.","example":"Cùng 10 thợ, cải tiến làm 150 thay 100 áo là chiều sâu; thuê thêm 5 thợ với quy trình cũ chủ yếu là chiều rộng."},"411":{"idea":"Hai nhóm cổ phiếu: thường và ưu đãi; khác quyền, lợi ích theo loại và điều lệ, không phải loại nào luôn lãi hơn.","example":"Cổ phiếu thường thường có quyền biểu quyết; cổ phiếu ưu đãi có quyền ưu tiên cụ thể. Cần xem loại ưu đãi, không tự suy tất cả đều giống nhau."},"412":{"idea":"Dùng sức lao động có thể tạo giá trị mới vượt giá trị của nó, là tính chất đặc biệt giúp giải thích m.","example":"Giá trị sức lao động 250, giá trị mới 400 → m=150. Đừng lấy giá trị cũ của nguyên liệu cộng vào rồi gọi tất cả là giá trị mới."},"413":{"idea":"Ba cạnh tranh trong độc quyền: với bên ngoài, giữa tổ chức độc quyền, bên trong tổ chức. Nhớ “ngoài–ngang–trong”.","example":"Tập đoàn tranh khách với hãng nhỏ, tranh thị phần với tập đoàn khác, thành viên tranh phần lợi ích trong liên minh."},"414":{"idea":"Tư bản cho vay là vốn tiền tệ nhường quyền dùng trong thời hạn để thu lợi tức; quyền sở hữu vẫn thuộc chủ cho vay.","example":"Cho doanh nghiệp vay vốn một năm rồi nhận gốc và lãi, khác mua hàng đứt đoạn hay góp vốn chịu kết quả kinh doanh như chủ sở hữu."},"415":{"idea":"Tái sản xuất xã hội cần tái tạo của cải, sức lao động, quan hệ sản xuất và môi trường.","example":"Nhà máy phải làm sản phẩm mới, phục hồi/đào tạo người, duy trì quan hệ tổ chức và xử lý nguồn nước; chỉ thêm hàng hóa chưa đủ bền vững."},"416":{"idea":"Thời gian chu chuyển = sản xuất + lưu thông, gồm cả thời gian chờ và bán hàng có liên quan.","example":"Làm hàng 10 ngày, mua đầu vào/chờ bán/thu tiền 20 ngày → vòng vốn 30 ngày; đừng chỉ đếm 10 ngày máy hoạt động."},"417":{"idea":"Theo đối tượng mua bán: hàng hóa vật chất và dịch vụ. Xem người mua nhận món đồ hay hoạt động phục vụ.","example":"Mua đôi giày là hàng hóa; thuê sửa giày là dịch vụ. Cùng cửa hàng có thể cung cấp cả hai."},"418":{"idea":"Khủng hoảng trong lý luận CNTB có căn nguyên khách quan từ mâu thuẫn hệ thống; không chỉ do một sai lầm cá nhân.","example":"Nhiều doanh nghiệp mở rộng riêng lẻ khi sức mua toàn xã hội hạn chế có thể gây thừa hàng diện rộng."},"419":{"idea":"p′ chịu ảnh hưởng m′, c/v, tốc độ chu chuyển và tiết kiệm c. Tách tử số lợi nhuận và mẫu vốn để hiểu.","example":"Giảm nguyên liệu lãng phí làm cần ít vốn hơn; quay vốn nhanh có thêm vòng sinh lợi; tăng vốn máy quá lớn có thể tăng mẫu số."},"420":{"idea":"Bốn lực thúc độc quyền: lực lượng sản xuất, cạnh tranh, khủng hoảng, tín dụng. Nhớ “Lớn–Đua–Sàng lọc–Gom vốn”.","example":"Công nghệ đòi nhà máy lớn; cạnh tranh và khủng hoảng loại hãng yếu; ngân hàng/cổ phần giúp gom vốn cho hãng mạnh."},"421":{"idea":"Khóa nêu xu hướng nhà tư bản muốn hạ chi phí sức lao động. Không suy ra lương thực tế mọi nước luôn giảm tuyệt đối.","example":"Chủ có động cơ giảm chi phí lương, nhưng kỹ năng, năng suất, tổ chức lao động và chính sách còn tác động mức lương thực nhận."},"422":{"idea":"Cung thấp hơn cầu tạo sức ép tăng giá, trong mô hình của đề giá có thể vượt giá trị. Xét các yếu tố khác không đổi.","example":"Chợ chỉ có 50 bó rau nhưng khách muốn mua 100 bó ở giá cũ: người mua tranh nhau, người bán có cơ hội tăng giá."},"423":{"idea":"Xã hội cần thiết = điều kiện sản xuất bình thường, kỹ năng và cường độ trung bình; không lấy riêng người nhanh/chậm nhất.","example":"Đa số xưởng cần 1 giờ may áo bằng kỹ thuật phổ biến; một người mới học cần 3 giờ không làm chuẩn xã hội thành 3 giờ."},"424":{"idea":"Đa ngành giúp mở cơ hội lợi nhuận, phân tán rủi ro và thích ứng cạnh tranh/quy định chống độc quyền trong cách phân tích của đề.","example":"Tập đoàn từ một ngành mở sang lĩnh vực khác thay vì chỉ thâu tóm thêm đối thủ cùng ngành; không có nghĩa đa ngành tự động hợp pháp mọi hành vi."},"425":{"idea":"Singapore thuộc nhóm nền kinh tế công nghiệp mới thường nêu ở châu Á. Đặt cạnh Hàn Quốc, Đài Loan, Hồng Kông để nhớ nhóm.","example":"Hình dung cảng, công nghiệp và dịch vụ phát triển nhanh tại Singapore; đừng xếp Anh, nơi khởi đầu công nghiệp hóa, vào nhóm “mới” này."},"426":{"idea":"4 giờ đầu tạo 15 giá trị mới bù tiền công ngày; 4 giờ sau tạo thêm 15 m. Muốn làm tiếp phải có thêm nguyên liệu và hao mòn.","example":"c cả ngày=2×(50+5)=110; v=15; m=15 → tổng giá trị 140. Bán đủ giá trị, trừ 125 chi phí còn 15; không trả thêm v trong giả định ngày 8 giờ đã thỏa thuận."},"427":{"idea":"Kinh tế tri thức là nấc phát triển lực lượng sản xuất, không tự nó là một chế độ sở hữu mới.","example":"Cùng nhà máy nhưng tri thức thiết kế, dữ liệu, phần mềm giữ vai trò lớn hơn nguyên liệu thô; quan hệ sở hữu phải xét riêng."},"428":{"idea":"Thị trường là tổng hòa quan hệ trao đổi, không chỉ địa điểm có quầy hàng.","example":"Mua qua ứng dụng vẫn có quan hệ giá, người mua, người bán, cạnh tranh và thanh toán dù hai bên không gặp tại chợ."},"429":{"idea":"Yêu cầu hiệu quả là hao phí cá biệt không vượt mức xã hội cần thiết; bằng là hòa theo chuẩn, thấp hơn có lợi thế. Khóa chỉ “=” quá hẹp.","example":"Chuẩn 2 giờ, xưởng làm 1,5 giờ vẫn đáp ứng và có lợi hơn; không phải làm nhanh hơn chuẩn là vi phạm quy luật."},"430":{"idea":"Nội bộ ngành cạnh tranh giữa người làm cùng loại hàng, hình thành giá trị thị trường; giữa ngành dẫn tới lợi nhuận bình quân.","example":"Các xưởng may áo có chi phí khác nhau nhưng hàng cùng loại gặp một mặt bằng thị trường; vốn chuyển từ may sang thép lại là chuyện giữa ngành."},"431":{"idea":"Một số đối tượng mua bán có giá cả dù không là sản phẩm lao động theo nghĩa thông thường, như đất tự nhiên. Không gộp mọi tài sản vô hình thành “không có lao động”.","example":"Mảnh đất tự nhiên chưa cải tạo vẫn được mua bán; giá phụ thuộc quyền sở hữu và khả năng thu lợi, không do lao động tạo ra bản thân đất tự nhiên."},"432":{"idea":"Tái sản xuất là sản xuất lặp lại, phục hồi liên tục vì xã hội phải tiêu dùng liên tục.","example":"Tiệm bánh không chỉ nướng một mẻ rồi hết: mua bột, làm, bán, bổ sung đầu vào để ngày sau tiếp tục."},"433":{"idea":"Theo nghĩa trừu tượng, thị trường là hệ thống quan hệ mua bán; theo nghĩa hẹp có thể là nơi giao dịch.","example":"Sàn đặt xe có người cung cấp, khách, giá và thanh toán nên thuộc thị trường dù không có gian hàng vật lý."},"434":{"idea":"v là phần vốn mua sức lao động, biểu hiện ở tiền công; lao động sống được sử dụng mới tạo giá trị mới.","example":"Trong 100 vốn, 20 trả sức lao động là v; 80 mua máy/nguyên liệu là c, dù cả hai ban đầu đều chi bằng tiền."},"435":{"idea":"Cấu tạo kỹ thuật là tỷ lệ hiện vật tư liệu sản xuất/lao động; cấu tạo giá trị dùng tiền c/v.","example":"10 máy do 5 người vận hành → 2 máy/người là chỉ báo kỹ thuật; 800 triệu/200 triệu là tỷ lệ giá trị."},"436":{"idea":"Địa tô tư bản là phần m vượt lợi nhuận bình quân mà nhà tư bản nông nghiệp nộp chủ đất.","example":"Nếu thu m=50, giữ lợi nhuận bình quân 30, phần 20 có thể thành tô trong ví dụ; đừng coi toàn bộ m đều giao chủ đất."},"437":{"idea":"Công nhân bán quyền sử dụng sức lao động trong thời hạn, không bán bản thân hay bán “lao động” đã tồn tại sẵn.","example":"Ký hợp đồng làm 8 giờ/ngày là cho sử dụng khả năng làm việc; người lao động vẫn là chủ thể tự do về thân thể."},"438":{"idea":"Thị trường phân bổ nguồn lực qua tín hiệu giá, lợi nhuận và cạnh tranh.","example":"Nhu cầu sửa xe tăng làm thợ và vốn chuyển vào mở tiệm; không cần mỗi khách trực tiếp ra lệnh tuyển thêm thợ."},"439":{"idea":"Trực tiếp có tham gia kiểm soát/quản lý đầu tư; gián tiếp chủ yếu qua vốn cho vay hoặc chứng khoán không trực tiếp điều hành.","example":"Xây và quản lý nhà máy ở nước ngoài khác mua ít trái phiếu để nhận lợi tức; đừng chỉ nhìn tiền có đi qua ngân hàng hay không."},"440":{"idea":"Syndicate: độc lập sản xuất, chung lưu thông. Đề viết “mất độc quyền” có khả năng muốn nói “mất độc lập”.","example":"Các xưởng tự làm hàng nhưng bán qua một ban bán hàng chung; không phải tự định toàn bộ khâu tiêu thụ như Cartel."},"441":{"idea":"Độc quyền là một giai đoạn của cùng phương thức tư bản chủ nghĩa, không phải phương thức sản xuất hoàn toàn khác.","example":"Sở hữu tư bản và lao động làm thuê vẫn còn, nhưng doanh nghiệp lớn chi phối nhiều hơn so với giai đoạn tự do cạnh tranh."},"442":{"idea":"Lao động trừu tượng tạo giá trị; cụ thể tạo giá trị sử dụng. Dùng hai cặp từ để tránh tráo.","example":"Nghề làm bánh tạo món ăn có ích; hao phí lao động nói chung trong bánh là mặt xét khi phân tích giá trị."},"443":{"idea":"Ba tác động quy luật giá trị: điều tiết sản xuất/lưu thông, thúc cải tiến, phân hóa người sản xuất.","example":"Giá cao hút vốn vào ngành; cạnh tranh buộc làm rẻ hơn; người hiệu quả lãi, người kém thua lỗ. Một chuỗi có cả ba tác động."},"444":{"idea":"c không tăng lượng giá trị trong sản xuất, được bảo tồn/chuyển vào sản phẩm; có thể chuyển dần nếu là máy, chuyển hết nếu là nguyên liệu.","example":"Bột 10 chuyển 10 trong mẻ; máy chỉ chuyển phần hao mòn. “Nguyên vẹn” không có nghĩa mọi c chuyển hết ngay một lần."},"445":{"idea":"Muốn hao phí cá biệt thấp hơn xã hội, người sản xuất có động lực đổi kỹ thuật và tăng năng suất.","example":"Hai tiệm cùng bán mức giá thị trường, tiệm giảm lãng phí và làm nhanh hơn có lợi thế, thúc các tiệm khác cải tiến theo."},"446":{"idea":"Lao động giản đơn không cần đào tạo chuyên môn đặc biệt; vẫn có thể cần hướng dẫn cơ bản và điều kiện an toàn.","example":"Xếp hàng hóa theo chỉ dẫn đơn giản khác sửa vi mạch đòi học nghề. “Không chuyên môn” không có nghĩa không cần kỹ năng nào."},"447":{"idea":"Ngân hàng độc quyền từ trung gian thanh toán trở thành trung tâm chi phối vốn, đầu tư và công nghiệp. “Mọi hoạt động” trong đáp án là cách nói khái quát mạnh.","example":"Ngân hàng vừa cấp tín dụng vừa nắm cổ phần có thể ảnh hưởng kế hoạch doanh nghiệp, không chỉ chuyển tiền giữa hai tài khoản."},"448":{"idea":"T′=T+ΔT, với ΔT>0. Dấu phẩy biểu thị tiền trở về lớn hơn tiền ứng ra.","example":"Ứng T=100, thu T′=120 → ΔT=20. Không nhầm T′ là riêng phần lãi 20; T′ gồm cả gốc và phần tăng."},"449":{"idea":"Tuần hoàn và chu chuyển là hai cách xem sự vận động tư bản, có cả sản xuất và lưu thông. Đề dùng “lưu thông” theo nghĩa rộng.","example":"Một vòng tiền–đầu vào–sản xuất–hàng–tiền; xét hình thái là tuần hoàn, xét lặp lại và tốc độ là chu chuyển."},"450":{"idea":"Hoạch định chính sách thuộc nhà nước/chủ thể quản lý; thị trường truyền tín hiệu và phân bổ qua giao dịch.","example":"Giá xăng phản ánh các tác động thị trường; quyết định chính sách thuế là hành động hoạch định, không phải bản thân thị trường ban luật."},"451":{"idea":"Các giá trị giàu mạnh, dân chủ, công bằng, văn minh là khát vọng rộng rãi; cách thực hiện và mức ưu tiên giữa quốc gia khác nhau.","example":"Người dân ở nhiều nơi đều mong đời sống tốt và xã hội công bằng; không suy ra tất cả quốc gia có mô hình kinh tế giống nhau."},"452":{"idea":"Hàng hóa đặc biệt là sức lao động: sử dụng tạo v+m, vượt giá trị sức lao động v.","example":"Một ngày lao động tạo 500 giá trị mới, giá trị sức lao động 300 → m=200. Máy móc chỉ chuyển giá trị cũ, không có đặc điểm này theo lý luận."},"453":{"idea":"Cung và cầu tương tác hình thành giá; mức cân bằng là nơi lượng cung bằng lượng cầu, không phải mọi giá thực tế đều đang cân bằng.","example":"Ở giá 30 nghìn, quán cung 100 tô và khách muốn mua đúng 100: điểm cân bằng trong ví dụ; giá khác có thể thừa hoặc thiếu."},"454":{"idea":"Bốn thành tố: luật chơi, người chơi, cách vận hành, thị trường. Nhớ như một cuộc chơi có đủ hệ thống.","example":"Kinh doanh trực tuyến cần luật, người mua/bán, cơ chế giao dịch và các thị trường thanh toán/vận chuyển; thiếu một phần sẽ vận hành khó."},"455":{"idea":"Điểm chung H–T–H và T–H–T′: cùng có tiền/hàng, cùng mua/bán. Khác thứ tự và mục đích.","example":"Bán rau lấy tiền mua gạo là H–T–H; ứng tiền mua đầu vào để thu nhiều tiền hơn là T–H–T′. Nhìn hai hành vi chung trước."},"456":{"idea":"Năng suất chịu kỹ năng, khoa học, tổ chức, tư liệu sản xuất và tự nhiên. Nhớ “Thợ–Khoa học–Phối hợp–Máy–Môi trường”.","example":"Cùng giống lúa, người có kỹ thuật, máy tốt, phối hợp tốt và đất/thời tiết thuận lợi có thể thu nhiều hơn mỗi đơn vị lao động."},"457":{"idea":"Mục tiêu xã hội năm giá trị đi với hài hòa lợi ích các thành phần, không chỉ tăng lợi nhuận một nhóm.","example":"Dự án phát triển cần lợi cho doanh nghiệp, người lao động và cộng đồng; nếu một bên hưởng hết còn bên khác chịu thiệt thì chưa hài hòa."},"458":{"idea":"Concern và Conglomerate là hình thức liên kết đa ngành mới trong bài. Concern thường có quan hệ liên kết; Conglomerate đa dạng cả ngành ít liên quan.","example":"Tập đoàn gồm nguyên liệu–chế biến–phân phối khác danh mục vừa thực phẩm vừa tài chính vừa thiết bị không cùng chuỗi."},"459":{"idea":"Sản lượng tăng mà giá trị đơn vị giữ nguyên trong cùng thời gian gợi tăng cường độ: nhiều hao phí lao động hơn.","example":"10 món tổng 100 → 20 món tổng 200, mỗi món vẫn 10. Nếu năng suất tăng thuần túy thì giá trị đơn vị phải giảm trong giả định chuẩn."},"460":{"idea":"Thị trường có hoạt động phong phú vì nhiều chủ thể, nhu cầu, sản phẩm và hình thức giao dịch cùng tồn tại.","example":"Mua bún, thuê nhà, vay vốn, học trực tuyến, xuất khẩu: đều là hoạt động kinh tế nhưng khác đối tượng và cách tổ chức."},"461":{"idea":"Giá trị là lao động xã hội của người sản xuất hàng hóa kết tinh trong sản phẩm. Không nhìn bằng mắt như màu, kích cỡ.","example":"Hai chiếc áo nhìn giống nhau nhưng điều kiện lao động xã hội để làm ra chúng giúp phân tích lượng giá trị; quan hệ trao đổi biểu hiện giá trị."},"462":{"idea":"Độc quyền có khả năng tập trung nguồn lực lớn cho nghiên cứu; đó là mặt tích cực, không bảo đảm luôn đổi mới.","example":"Tập đoàn tài trợ phòng thí nghiệm nhiều năm là khả năng thuận lợi; nếu muốn bảo vệ công nghệ cũ, họ cũng có thể trì hoãn đổi mới."},"463":{"idea":"Kinh tế thị trường định hướng XHCN là mô hình kinh tế tổng quát của thời kỳ quá độ ở Việt Nam theo giáo trình.","example":"Đây là cách tổ chức chung của nền kinh tế, không chỉ tên một ngành, một doanh nghiệp hay một kế hoạch ngắn hạn."},"464":{"idea":"Quan hệ kinh tế biểu hiện trước hết qua lợi ích: mỗi vị trí có điều muốn đạt về vật chất.","example":"Người lao động quan tâm lương/điều kiện, chủ quan tâm lợi nhuận, nhà nước quan tâm nguồn lực công; nhìn lợi ích để nhận ra quan hệ giữa họ."},"465":{"idea":"Giá trị được biểu hiện trong quan hệ trao đổi; công dụng có thể quan sát qua sử dụng.","example":"Cầm áo biết dùng để mặc; muốn thấy giá trị biểu hiện phải đặt áo trong quan hệ đổi với hàng khác hoặc tiền."},"466":{"idea":"Lao động cụ thể tạo giá trị sử dụng, tức hình thức có ích của sản phẩm.","example":"Thợ may tạo áo mặc, thợ xây tạo nhà ở; khác nghề làm ra công dụng khác nhau, dù đều hao phí sức lao động."},"467":{"idea":"Mức liên kết tăng: Cartel → Syndicate → Trust → Consortium. Nhớ thỏa thuận → chung bán → chung cả sản xuất/bán/tài vụ → liên minh quy mô rộng.","example":"Hình dung quyền tự quyết của xưởng thu hẹp dần từ tự làm tự bán tới ban quản trị chung; tên gọi cần gắn đúng mức liên kết."},"468":{"idea":"Thị trường phá tính tự cấp tự túc bằng chuyên môn hóa và trao đổi, mở đường nâng năng suất.","example":"Hộ không còn phải tự dệt, tự rèn mọi công cụ; chuyên trồng sản phẩm có lợi thế rồi mua thứ người khác làm tốt hơn."},"469":{"idea":"ASEM → sáng lập năm 1996; ASEAN → gia nhập 1995. Chênh một năm nên dễ nhầm.","example":"Ghi hai cột liền nhau: 1995 vào tổ chức Đông Nam Á; 1996 cùng sáng lập diễn đàn Á–Âu, phạm vi hợp tác rộng hơn."},"470":{"idea":"Nội bộ độc quyền vẫn tranh vị thế, cổ phần chi phối và phần lợi ích. Liên minh không xóa khác biệt lợi ích thành viên.","example":"Các công ty cùng tổ chức bán hàng chung nhưng vẫn tranh hạn ngạch bán và tỷ lệ lợi nhuận được chia."},"471":{"idea":"Hình thái chung: mọi hàng biểu hiện giá trị qua một vật ngang giá chung. Chỉ khi vai trò đó cố định vào tiền mới là hình thái tiền tệ.","example":"Cả làng quy gạo, vải, muối qua bò là vật ngang giá chung giả định; chưa cần bò đã là tiền tệ hoàn chỉnh."},"472":{"idea":"Hàng hóa cá nhân có tính cạnh tranh trong tiêu dùng: phần một người dùng không còn cho người khác dùng phần ấy.","example":"Bạn ăn một tô bún thì người khác không thể ăn lại chính tô đó; khác ánh sáng đèn đường nhiều người cùng hưởng."},"473":{"idea":"Thuế là khoản thu theo quyền lực nhà nước, không phải hình thái riêng của m như lợi nhuận, lợi tức, địa tô trong danh mục bài học.","example":"Lãi cho vay và tô đất là cách phân chia nguồn thu trong lý luận; thuế có thể đánh vào nhiều loại thu nhập nên không đồng nhất bản chất với m."},"474":{"idea":"Câu nguồn chọn tạo giá trị mới và làm tăng giá trị, nhưng định nghĩa đầy đủ thường là thống nhất sản xuất giá trị sử dụng với sản xuất m. Lựa chọn đang thiếu vế công dụng.","example":"Xưởng phải làm ra đôi giày dùng được, đồng thời tạo giá trị vượt vốn sức lao động; chỉ hai cụm gần nghĩa về giá trị chưa nói đủ quá trình."},"475":{"idea":"Thể chế cần hoàn thiện vì hình thành/phát triển còn chưa đồng bộ, quản lý cần nâng năng lực, hiệu quả thực thi còn hạn chế.","example":"Luật cho mở doanh nghiệp nhanh nhưng đất đai, vốn, thủ tục liên quan chưa khớp sẽ làm hoạt động bị nghẽn."},"476":{"idea":"Tích tụ và tập trung đạt mức cao tạo điều kiện độc quyền. Quy mô lớn giúp chi phối nguồn cung và quan hệ thị trường.","example":"Nhiều xưởng sau tái đầu tư và sáp nhập còn vài tập đoàn kiểm soát phần lớn ngành: sự tập trung đổi sức mạnh thị trường."},"477":{"idea":"Hoàn thiện sở hữu gồm quyền tài sản, đất đai và tài nguyên; phải rõ quyền, trách nhiệm, cách sử dụng hiệu quả.","example":"Một dự án cần biết ai có quyền dùng đất, khai thác tài nguyên đến đâu và ai chịu trách nhiệm lãng phí/thiệt hại."},"478":{"idea":"Hàng hóa có lao động chung kết tinh; trao đổi ngang giá xét lượng hàng có tổng giá trị tương đương, không bắt buộc một đổi một.","example":"1 áo có thể đổi 2 khăn nếu chúng chứa lượng lao động xã hội tương đương; công dụng vẫn khác nhau."},"479":{"idea":"Điền “xã hội chủ nghĩa / thị trường”: định hướng mục tiêu và quy luật vận hành cùng tồn tại.","example":"Doanh nghiệp vẫn tính giá, cung cầu, cạnh tranh trong khi chính sách hướng tới tiến bộ và công bằng; không thay quy luật thị trường bằng mong muốn."},"480":{"idea":"c tồn tại ở tư liệu sản xuất: máy, nguyên liệu, nhiên liệu, vật liệu. Chúng chuyển giá trị, không tạo giá trị mới theo Mác.","example":"Xưởng bánh: lò, bột, điện đã tiêu dùng thuộc phần c; vốn mua sức lao động thuộc v."},"481":{"idea":"Nghiên cứu quan hệ người–người trong từng khâu và giữa các khâu của tái sản xuất, như một chỉnh thể.","example":"Ai sản xuất, cách chia thu nhập, ai mua bán, ai tiêu dùng liên hệ nhau; không tách một khâu rồi bỏ quan hệ với khâu khác."},"482":{"idea":"Quy luật kinh tế khách quan: không do ý muốn cá nhân tạo hay xóa, dù hoạt động con người làm nó biểu hiện.","example":"Ra lệnh “mọi người phải thích món này” không tự tạo sức mua; người làm chính sách phải hiểu động cơ và điều kiện thực tế."},"483":{"idea":"Chuẩn là hao phí lao động xã hội cần thiết; người sản xuất phải hướng hao phí cá biệt phù hợp hoặc thấp hơn để có lợi thế.","example":"Thị trường thường cần 1 giờ/món, xưởng mất 3 giờ sẽ khó bán đủ bù chi phí. Làm chậm không tự tăng giá trị xã hội."},"484":{"idea":"Lợi ích kinh tế là lợi ích vật chất nhận từ hoạt động kinh tế, gắn nhu cầu và động cơ.","example":"Lương của người làm, lợi nhuận chủ quán, thu nhập người cho thuê là các lợi ích khác nhau trong cùng mạng lưới hoạt động."},"485":{"idea":"Chọn đủ: tự do thân thể + thiếu tư liệu sản xuất. Nhớ “được quyền bán sức lao động, cần phải bán để sống”.","example":"Người lao động tự chọn nơi làm nhưng không có đủ ruộng/xưởng tự nuôi mình; khác nô lệ bị mua bán cả con người."},"486":{"idea":"H–T–H: bán hàng mình có lấy tiền, mua hàng mình cần. Mục đích cuối là công dụng, không phải tiền lớn hơn.","example":"Bán rau → có tiền → mua gạo để ăn. Điểm đầu và cuối đều là hàng nhưng có công dụng khác nhau."},"487":{"idea":"Mâu thuẫn cơ bản: lực lượng sản xuất xã hội hóa cao đối lập chiếm hữu tư nhân tư bản chủ nghĩa.","example":"Hàng nghìn người hợp tác làm sản phẩm, quyền sở hữu và quyết định phần dư lại tập trung ở chủ tư bản."},"488":{"idea":"Syndicate giữ độc lập làm hàng nhưng chung khâu lưu thông. Nhớ “riêng làm–chung bán”.","example":"Mỗi xưởng tự tổ chức thợ/máy, một ban chung nhận đơn và tiêu thụ; Trust liên kết sâu hơn, chung cả sản xuất và tài vụ."},"489":{"idea":"Lợi ích vừa thống nhất vừa mâu thuẫn: có việc cùng cần nhưng phần hưởng có thể đối lập.","example":"Chủ và thợ đều muốn quán đông khách; khi chia doanh thu, chủ muốn giữ lợi nhuận, thợ muốn tăng lương. Cần cơ chế hài hòa."},"490":{"idea":"Ba mô hình tiêu biểu trong chương: cổ điển, Liên Xô, Nhật Bản/NICs. Nhớ “đi đầu–kế hoạch–rút ngắn”.","example":"Cổ điển tự phát triển công nghệ lâu dài; Liên Xô ưu tiên công nghiệp nặng; đi sau tận dụng thành tựu để tăng tốc."},"491":{"idea":"Sức lao động cũng có hai thuộc tính: giá trị và giá trị sử dụng; tính đặc biệt nằm ở công dụng tạo giá trị mới.","example":"Giá trị gắn chi phí tái sản xuất sức lao động; sử dụng trong ngày làm có thể tạo v+m. Đừng chọn tiền công như thuộc tính thứ ba."},"492":{"idea":"Phân chia thị trường hàng hóa/dịch vụ dựa vào đối tượng trao đổi, không dựa người mua online hay trực tiếp.","example":"Bán xe là hàng hóa, cho thuê/sửa xe là dịch vụ; cùng giao dịch qua ứng dụng nhưng khác đối tượng."},"493":{"idea":"Adam Smith nêu hai mục tiêu: sinh kế/thu nhập cho dân và nguồn thu nhà nước làm việc công. Nhớ “dân sống–nước làm việc chung”.","example":"Người dân có thu nhập từ hoạt động kinh tế, nhà nước có ngân sách xây hạ tầng; hai phía gắn nhau nhưng không phải một khoản thu."},"494":{"idea":"Bộ năm giá trị toàn diện là mục tiêu xã hội tương lai cần phấn đấu, không phải trạng thái đã hoàn tất ở mọi quốc gia.","example":"Một nơi giàu nhưng bất công hoặc thiếu dân chủ chưa hội đủ bộ năm; kiểm từng mặt thay vì chỉ nhìn GDP."},"495":{"idea":"Ba yếu tố sản xuất: sức lao động, đối tượng lao động, tư liệu lao động. Nhớ “người–thứ được làm–thứ dùng để làm”.","example":"Nấu bún: người nấu dùng bếp/nồi tác động lên nguyên liệu. Người, nguyên liệu và dụng cụ giữ ba vai trò khác nhau."},"496":{"idea":"Trong đề, cạnh tranh tăng được nhìn như sức ép/thách thức với doanh nghiệp yếu; bản thân cạnh tranh vẫn có mặt tích cực thúc đổi mới.","example":"Hàng nhập tốt hơn buộc xưởng nội địa cải tiến nhưng cũng có thể khiến xưởng kém hiệu quả mất khách. Đừng học “cạnh tranh luôn xấu”."},"497":{"idea":"Ba đại biểu cổ điển Anh: Petty–Smith–Ricardo. Tách khỏi trọng nông Pháp và Mác–Lênin.","example":"Dùng chuỗi “đặt nền–hệ thống hóa–phát triển” gắn ba tên, tránh lẫn Quesnay của trọng nông vào nhóm Anh."},"498":{"idea":"Đặc trưng phổ biến: nhiều chủ thể/sở hữu, thị trường phân bổ, giá theo thị trường, kinh tế mở.","example":"Nhiều cửa hàng cùng mua bán, tự chọn đầu vào, phản ứng giá và giao dịch với bên ngoài; không chỉ có một chủ tự phân phối mọi thứ."},"499":{"idea":"Tư bản thương nghiệp là phần tách ra chuyên khâu lưu thông hàng hóa của tư bản công nghiệp.","example":"Nhà máy tập trung làm giày, doanh nghiệp thương mại chuyên mua/bán và phân phối giày; sự chuyên môn hóa giúp thực hiện giá trị hàng."},"500":{"idea":"Trong cách phân loại của đề, tuyệt đối gồm kéo dài giờ và tăng cường độ, tức tăng hao phí lao động; tương đối giảm thời gian tất yếu nhờ năng suất xã hội.","example":"Làm 10 thay 8 giờ hoặc gắng sức hơn trong ca đều tăng lượng lao động; đổi công nghệ hạ giá trị sức lao động là logic tương đối."},"501":{"idea":"Lợi ích kinh tế bộc lộ mục đích và động cơ trong quan hệ giữa các chủ thể. Hỏi “tham gia để được gì?”.","example":"Người làm muốn lương, chủ muốn lợi nhuận, khách muốn hàng đáng tiền: ba động cơ cùng tác động một giao dịch."},"502":{"idea":"Tăng trưởng phải đi cùng tiến bộ, công bằng và bền vững; không đợi giàu rồi mới xử lý mọi hậu quả xã hội.","example":"Khu công nghiệp tạo việc làm đồng thời cần nhà ở, bảo hiểm, xử lý nước thải; sản lượng tăng nhưng chi phí xã hội quá lớn chưa đạt mục tiêu."},"503":{"idea":"Doanh nghiệp nhỏ có bộ máy gọn nên dễ đổi sản phẩm/cách phục vụ, dù thường yếu vốn và quy mô.","example":"Quán bún nhỏ đổi món theo khách trong vài ngày; chuỗi lớn phải phối hợp nhiều khâu. Linh hoạt không có nghĩa luôn thắng doanh nghiệp lớn."},"504":{"idea":"Sở hữu hiện thực nảy sinh và vận động trong sản xuất, tái sản xuất; không chỉ là một dòng tên trên giấy.","example":"Quyền đối với đất, máy, sản phẩm quyết ai sử dụng, quản lý và hưởng lợi qua các vòng sản xuất; pháp lý ghi nhận nhưng đời sống kinh tế làm nó hiện thực."},"505":{"idea":"Biểu hiện mới là TNC lớn cùng tồn tại với doanh nghiệp vừa/nhỏ; độc quyền không xóa sạch đơn vị nhỏ.","example":"Một tập đoàn toàn cầu có mạng nhà cung cấp, cửa hàng và doanh nghiệp dịch vụ nhỏ xung quanh; quy mô khác nhau cùng tồn tại."},"506":{"idea":"Chọn đủ các nhóm: lực lượng sản xuất, cạnh tranh, khủng hoảng và tín dụng. Chúng cùng thúc tập trung quy mô lớn.","example":"Công nghệ đòi vốn lớn; ngân hàng gom vốn; cạnh tranh/khủng hoảng làm hãng yếu bị thâu tóm: chuỗi dẫn đến độc quyền."},"507":{"idea":"Cấu tạo hữu cơ là c/v khi tỷ lệ giá trị ấy do cấu tạo kỹ thuật quyết định và phản ánh thay đổi kỹ thuật.","example":"Thêm máy trên mỗi thợ làm cơ cấu vốn máy/nguyên liệu so với sức lao động đổi; biến động giá máy đơn thuần chưa đủ giải thích thay đổi kỹ thuật."},"508":{"idea":"Ba tính chất: khách quan, lịch sử, tác động qua hoạt động con người. Nhớ “không tùy ý–có điều kiện–qua hành vi”.","example":"Quy luật giá trị hoạt động trong kinh tế hàng hóa qua quyết định sản xuất/mua bán; không phải mệnh lệnh do một cá nhân ban hành."},"509":{"idea":"Phương án B bị dính chữ từ A nên chưa đủ sạch để xác định ý “không phải”. Cần sửa/đối chiếu nguồn trước khi học khóa.","example":"Phân biệt sở hữu nhà nước, quan hệ nhân sự, điều tiết với sở hữu tư nhân nói chung; không dùng một chuỗi hai ý bị nối nhầm làm định nghĩa."},"510":{"idea":"Trong phân tích của giáo trình, xuất vốn nhà nước có thể tạo ảnh hưởng kinh tế và nền tảng cho tư bản tư nhân đi theo.","example":"Tài trợ hạ tầng gắn điều kiện mua thiết bị/dịch vụ từ nước cấp vốn có thể mở đường cho doanh nghiệp nước đó; phải xét điều kiện cụ thể."},"511":{"idea":"Đại hội IX (2001) → mô hình kinh tế tổng quát thời kỳ quá độ. Mốc VI (1986) → khởi xướng Đổi mới.","example":"Nhớ “VI đổi hướng, IX gọi rõ mô hình” để không lấy cùng một đáp án cho hai câu lịch sử khác nhau."},"512":{"idea":"Theo giáo trình, DNNN tập trung ngành then chốt, quốc phòng/an ninh và lợi ích công cộng; không phải dàn trải mọi nghề có lãi.","example":"Hạ tầng thiết yếu và dịch vụ công quan trọng là hình ảnh gợi nhớ, khác việc nhà nước phải mở từng quán ăn hay cửa hàng nhỏ."},"513":{"idea":"Tiền tượng trưng có sức mua/mệnh giá vượt xa giá trị vật liệu. Phân biệt với vàng có giá trị vật liệu đáng kể.","example":"Tờ tiền mệnh giá lớn chỉ dùng ít giấy và mực, nhưng được chấp nhận thanh toán theo mệnh giá; không lấy chi phí in làm sức mua."},"514":{"idea":"m′ phản ánh trình độ khai thác lao động làm thuê: m so với v, hay giờ thặng dư so với giờ tất yếu.","example":"Cùng ngày 8 giờ, 4+4 cho m′=100%; 2+6 cho 300%. Tổng số công nhân không trực tiếp quyết định tỷ lệ này."},"515":{"idea":"Theo câu hỏi, định hướng thể hiện qua phân phối gắn lao động/hiệu quả và phúc lợi; hệ thống thực tế còn có các hình thức phân phối khác.","example":"Thu nhập theo đóng góp sản xuất đi cùng hỗ trợ y tế, giáo dục, an sinh; không chỉ chia đều tiền bất kể đóng góp hay nhu cầu."},"516":{"idea":"Tính lịch sử: nghiên cứu quy luật kinh tế trong điều kiện, phương thức sản xuất cụ thể và sự biến đổi của chúng.","example":"Quan hệ địa chủ–nông dân khác chủ tư bản–lao động làm thuê; không lấy một hình thức quan hệ làm bất biến cho mọi thời đại."},"517":{"idea":"Cạnh tranh giữa ngành nhằm tìm nơi đầu tư có tỷ suất sinh lời tốt nhất.","example":"Có 100 vốn: ngành A lãi 5, ngành B lãi 15 thu hút vốn sang B; dòng vốn ấy góp phần làm tỷ suất lợi nhuận bình quân hóa."},"518":{"idea":"Ba giới hạn đề yêu cầu: mục đích lợi ích thiểu số, chiến tranh/xung đột, phân hóa giàu nghèo. Đây là khung đánh giá trong giáo trình.","example":"Sản xuất nhiều của cải hơn không tự bảo đảm thành quả chia đều hay quan hệ quốc tế hòa bình; tách thành tựu sản xuất với phân phối/quyền lực."},"519":{"idea":"Kinh tế thị trường là kinh tế hàng hóa ở trình độ cao: quan hệ thị trường trở thành cơ chế phân bổ phổ biến.","example":"Không chỉ vài hộ đổi đồ, mà lao động, vốn, hàng và dịch vụ đều liên kết qua mạng thị trường rộng lớn."},"520":{"idea":"Hai yêu cầu: yếu tố thị trường đồng bộ và các thị trường liên thông. “Bộ phận đủ” phải đi cùng “kết nối chạy được”.","example":"Xưởng có đơn hàng nhưng không tiếp cận được vốn/lao động/đất thì không mở rộng nổi; thị trường sản phẩm không thể hoạt động tách các thị trường đầu vào."},"521":{"idea":"CNH là con đường phát triển sức sản xuất và xây cơ sở vật chất kỹ thuật của CNXH trong lý luận môn học.","example":"Muốn sản xuất hiệu quả hơn cần máy móc, kỹ năng, hạ tầng; mục tiêu xã hội phải có nền vật chất để thực hiện, không chỉ tuyên bố."},"522":{"idea":"Quan hệ người lao động–người sử dụng lao động là một LOẠI quan hệ lợi ích; các lựa chọn khác là NHÂN TỐ tác động quan hệ ấy.","example":"Lương giữa thợ và chủ là quan hệ đang xét; năng suất, chính sách phân phối và hội nhập là những điều làm quan hệ đó thay đổi."},"523":{"idea":"Bốn nhóm công cụ: kế hoạch, pháp luật, tài chính–tiền tệ, đối ngoại. Chúng định hướng và điều tiết vĩ mô.","example":"Nhà nước có thể đầu tư công, đặt luật cạnh tranh, điều hành tiền tệ và thương mại; không trực tiếp chọn món thay cho mọi quán ăn."},"524":{"idea":"Trong các lựa chọn, chính trị và kinh tế là hai nhóm thuộc phân loại theo lĩnh vực cốt lõi. Danh mục đầy đủ của bài còn có xã hội.","example":"Quy tắc tổ chức quyền lực thuộc chính trị, quy tắc sản xuất/mua bán thuộc kinh tế; công/tư là một tiêu chí phân loại khác."},"525":{"idea":"Theo Lênin, tự do cạnh tranh thúc tích tụ/tập trung; đến mức cao sinh độc quyền. Nhớ đường đi ba bước.","example":"Nhiều doanh nghiệp cạnh tranh, người mạnh mở rộng/thâu tóm, vài hãng còn lại chi phối nguồn cung."},"526":{"idea":"m được nhìn như “con đẻ” toàn bộ vốn ứng trước thì mang hình thức lợi nhuận p. Câu hỏi đòi phạm trù gốc là m.","example":"Sổ chi phí gộp máy, vật liệu, lương thành 100; dư 20 được gọi lãi trên vốn 100, che đi nguồn gốc ở lao động thặng dư."},"527":{"idea":"Trình độ lực lượng sản xuất quyết định cơ sở nội dung/hình thức sở hữu; quan hệ sở hữu cũng tác động ngược trở lại.","example":"Một công cụ hộ gia đình và mạng nhà máy xã hội hóa lớn đòi hình thức huy động, quản lý tài sản khác nhau."},"528":{"idea":"Lao động cụ thể phản ánh tính tư nhân trong sản xuất hàng hóa: chủ tự chọn làm gì/cách nào. Trao đổi mới xác nhận phần lao động xã hội.","example":"Bạn tự chọn mẫu áo để may; nếu không ai mua, công việc riêng đó chưa được thị trường thừa nhận như dự kiến."},"529":{"idea":"Hoàn thiện sở hữu và phát triển các thành phần là một nhiệm vụ chủ yếu: rõ quyền tài sản, trách nhiệm và điều kiện hoạt động.","example":"Doanh nghiệp muốn đầu tư cần biết tài sản thuộc ai, được dùng/chuyển nhượng ra sao và quyền lợi có được bảo vệ không."},"530":{"idea":"Cung–cầu được thể hiện và điều tiết trực tiếp qua trao đổi trên thị trường, nối sản xuất với tiêu dùng.","example":"Quán làm nhiều bún nhưng ít khách, giá và lượng bán phản hồi để hôm sau giảm sản xuất; tín hiệu phát sinh ở khâu mua bán."},"531":{"idea":"Điểm chung là nhà nước quản lý vĩ mô bằng luật và chính sách; mức độ, mục tiêu cụ thể tùy nền kinh tế.","example":"Quy định an toàn thực phẩm áp cho các quán, còn quán tự quyết thực đơn theo khách; quản lý vĩ mô khác điều hành từng bếp."},"532":{"idea":"Ba mặt tiêu cực: méo cạnh tranh/hại người tiêu dùng, có thể kìm đổi mới, phân hóa giàu nghèo. Không mâu thuẫn khả năng tài trợ nghiên cứu của doanh nghiệp lớn.","example":"Hãng đang lãi cao từ công nghệ cũ có thể trì hoãn thay mới và giữ giá cao; khả năng có vốn R&D không bảo đảm động cơ đổi mới luôn mạnh."},"533":{"idea":"Mục đích xuyên suốt: góp phần giàu có, văn minh và phát triển toàn diện; tìm quy luật là cơ sở khoa học để hướng tới mục đích ấy.","example":"Hiểu quan hệ lợi ích để thiết kế cách phát triển vừa nâng sản lượng vừa cải thiện đời sống, thay vì chỉ thuộc tên học thuyết."},"534":{"idea":"Điều kiện khách quan làm kinh tế thị trường hình thành; cơ chế ấy có khả năng thúc lực lượng sản xuất nên việc vận dụng có cơ sở thực tế.","example":"Khi chủ thể chuyên môn hóa và độc lập kinh tế, mua bán phát triển; cạnh tranh và giá thúc tìm cách sản xuất hiệu quả hơn."},"535":{"idea":"Bốn chức năng: nhận thức–thực tiễn–phương pháp luận–tư tưởng. Nhớ “Hiểu–Làm–Cách nghĩ–Định hướng”.","example":"Hiểu quy luật, dùng để quyết định, biết phương pháp phân tích, hình thành cách nhìn lợi ích xã hội: bốn việc sau khi học một chủ đề."},"536":{"idea":"Chế độ tham dự dùng cổ phần khống chế để chi phối công ty mẹ, từ đó công ty con/cháu. Không nhất thiết sở hữu 100%.","example":"A kiểm soát công ty mẹ, mẹ giữ quyền chi phối công ty con; A ảnh hưởng một chuỗi vốn lớn hơn số vốn trực tiếp bỏ ra."},"537":{"idea":"Hai ý cùng đúng: vận hành theo quy luật thị trường và có điều tiết nhà nước dưới lãnh đạo của Đảng theo mô hình Việt Nam.","example":"Giá, cạnh tranh hướng quyết định kinh doanh; luật, chính sách và mục tiêu xã hội định hướng chung. Một vế không xóa vế kia."},"538":{"idea":"Bán sức lao động: chính người lao động bán quyền dùng khả năng làm việc trong thời hạn. Bán nô lệ: người khác bán cả con người như tài sản.","example":"Hợp đồng thuê lao động không cho chủ sở hữu thân thể người làm; quyền tự do thân thể và đối tượng bị bán là hai điểm khác cốt lõi."}};
